    // 4. Process Duplicate File (Excel 3)
    // Formula: =VLOOKUP(A2,'[Master Hold Report .xlsx]Master Hold Report'!$G:$G,1,0)
    const dupSheetName = dupWb.SheetNames.find((name: string) => name.toLowerCase().includes('master hold report')) || dupWb.SheetNames[0];
    const dupWs = dupWb.Sheets[dupSheetName];
    const dupData: Row[] = XLSX.utils.sheet_to_json(dupWs, { header: 1, defval: "" });

    const dupLookup = new Set<number>();
     for (let i = 1; i < dupData.length; i++) {
        const row = dupData[i];
        const key = Number(row[6]); // Column G
        if (!isNaN(key)) {
            dupLookup.add(key);
        }
    }

    // Prepare Keywords
    const keywords = defenseKeywords.split(',').map(k => k.trim().toLowerCase()).filter(k => k.length > 0);

    // 5. Combine data and perform VLOOKUPs on Raw Data (Excel 1)
    const finalData = rawData.map((row, index) => {
        if (index === 0) {
            return [...row, 'Info_VLOOKUP', 'Dup_VLOOKUP', 'Export_Value', 'Defense_Match'];
        }
        const key = row[0];

        // Lookup 1: Info (from File 2, Sheet3/Default, Col G)
        const infoValue = infoLookup.get(key) ?? '#N/A';

        // Lookup 2: Dup (from File 3)
        const dupValue = dupLookup.has(key) ? key : '#N/A';

        // Lookup 3: Export/Defense (from File 2, Sheet2 or Fallback, Col H)
        const exportValueRaw = exportLookup.get(key);
        const exportValue = exportValueRaw !== undefined ? exportValueRaw : '#N/A';

        // Check Keywords
        let isDefenseMatch = false;
        if (exportValueRaw && keywords.length > 0) {
            const valLower = exportValueRaw.toLowerCase();
            isDefenseMatch = keywords.some(kw => valLower.includes(kw));
        }

        return [...row, infoValue, dupValue, exportValue, isDefenseMatch ? 'TRUE' : 'FALSE'];
    });

    return finalData;
};

/**
 * Assigns work, generates the final Excel file, and calculates pivot data.
 * @returns An object containing the .xlsx file data and the pivot table data.
 */
export const assignAndGenerateExcel = async (
    processedData: Row[],
    cnAssignees: string[],
    jpAssignees: string[],
    specialAssignees: string[],
    generalAssignees: string[],
    zraxMode: 'NONE' | 'PRIORITY' | 'ONLY' = 'NONE'
): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {

    const header = processedData.length > 0 ? [...processedData[0]] : [];
    if (processedData.length < 2) {
        const ws = XLSX.utils.aoa_to_sheet([header]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Assigned_Data');
        const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        return { fileData: new Uint8Array(wbout), pivotData: [] };
    }

    const dataRows = processedData.slice(1);

    const dupLookupIndex = header.findIndex((h: string) => h === 'Dup_VLOOKUP');
    if (dupLookupIndex === -1) {
        throw new Error("'Dup_VLOOKUP' column not found. Cannot perform filtering.");
    }

    // 1. Filter rows to keep only those with '#N/A' in 'Dup_VLOOKUP'
    let filteredRows = dataRows.filter(row => row[dupLookupIndex] === '#N/A');

    // 1.5 Apply ZRAX Logic (ZOP / OZ)
    // Original Column Z (index 25) became index 19 after removing 6 columns (B-G).
    // Logic: row[0] is A. row[1] is H (index 7). row[19] is Z (index 25).
    const Z_COLUMN_INDEX = 19;
    const ZRAX_KEYWORD = 'ZRAX';

    if (zraxMode === 'ONLY') {
        // OZ Mode: Keep ONLY rows containing "ZRAX" in original Col Z
        filteredRows = filteredRows.filter(row => String(row[Z_COLUMN_INDEX] || '').trim() === ZRAX_KEYWORD);
    } else if (zraxMode === 'PRIORITY') {
        // ZOP Mode: Sort ZRAX rows to the top
        const zraxRows: Row[] = [];
        const otherRows: Row[] = [];
        filteredRows.forEach(row => {
            if (String(row[Z_COLUMN_INDEX] || '').trim() === ZRAX_KEYWORD) {
                zraxRows.push(row);
            } else {
                otherRows.push(row);
            }
        });
        filteredRows = [...zraxRows, ...otherRows];
    }

    const infoLookupIndex = header.findIndex((h: string) => h === 'Info_VLOOKUP');
    if (infoLookupIndex === -1) {
        throw new Error("'Info_VLOOKUP' column not found. Cannot perform assignment.");
    }

    const cnRows: Row[] = [];
    const jpRows: Row[] = [];
    const specialRows: Row[] = [];
    const generalRows: Row[] = [];

    const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY']);

    // 2. Categorize rows based on 'Info_VLOOKUP' value
    // Note: If 'PRIORITY' mode was used, the filteredRows are sorted with ZRAX first.
    // Iterating them in order preserves this sort within each category bucket.
    filteredRows.forEach((row: Row) => {
        const infoValue = row[infoLookupIndex] ? String(row[infoLookupIndex]).toUpperCase() : '';
        if (infoValue.includes('CN')) {
            cnRows.push([...row]);
        } else if (infoValue.includes('JP')) {
            jpRows.push([...row]);
        } else if (Array.from(specialCodes).some(code => infoValue.includes(code))) {
            specialRows.push([...row]);
        } else {
            generalRows.push([...row]);
        }
    });

    // 3. Assign work for each category
    const assignRows = (rows: Row[], assignees: string[], prefix: string) => {
         if (assignees.length > 0) {
            rows.forEach((row, index) => {
                row.unshift(assignees[index % assignees.length]);
            });
        } else {
            rows.forEach(row => row.unshift(`UNASSIGNED_${prefix}`));
        }
    }

    assignRows(cnRows, cnAssignees, 'CN');
    assignRows(jpRows, jpAssignees, 'JP');
    assignRows(specialRows, specialAssignees, 'SPECIAL');
    assignRows(generalRows, generalAssignees, 'GENERAL');

    // 4. Combine all assigned rows
    const finalAssignedRows = [...cnRows, ...jpRows, ...specialRows, ...generalRows];

    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });

    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({
        screener,
        count
    })).sort((a, b) => a.screener.localeCompare(b.screener));

    // 5. Prepare final sheet

    // 5.1. Find and remove the 'CTR' column
    const ctrIndex = header.findIndex((h: string) => h === 'CTR');
    if (ctrIndex !== -1) {
        header.splice(ctrIndex, 1);
        finalAssignedRows.forEach(row => {
            row.splice(ctrIndex + 1, 1); // +1 because we added 'Screener' at start conceptually
        });
    }

    // 5.2. Prepend 'Screener' to the modified header
    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];

    // 5.3. Create worksheet and apply header styling
    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);

    const headerStyle = {
        font: { bold: true },
        fill: { fgColor: { rgb: "FFD3D3D3" } }
    };

    const range = XLSX.utils.decode_range(finalWs['!ref']);
    if (range && range.e.r >= 0) { 
        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellAddress = XLSX.utils.encode_cell({ r: 0, c: C });
            const cell = finalWs[cellAddress];
            if (cell) {
                cell.s = headerStyle;
            }
        }
    }

    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'Assigned_Data');

    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    const fileData = new Uint8Array(wbout);

    return { fileData, pivotData };
};

export const processColumnA = async (file: File): Promise<{ uniqueNumbers: number[] }> => {
    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded.');
    }

    const buffer = await readFileAsArrayBuffer(file);
    const wb = XLSX.read(buffer, { type: 'array' });
    const ws = wb.Sheets[wb.SheetNames[0]];
    if (!ws) throw new Error("File is empty or corrupted.");

    const data: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });

    const seen = new Set<number>();
    for (let i = 0; i < data.length; i++) {
        const row = data[i];
        if (row && row.length > 0 && row[0] !== null) {
            const valA = Number(row[0]);
            if (!isNaN(valA)) {
                seen.add(valA);
            }
        }
    }

    return { uniqueNumbers: Array.from(seen).sort((a, b) => a - b) };
};

import React, { useState, useCallback } from 'react';
import type { ExcelFileState } from '../types';
import { runInitialProcessing, assignAndGenerateExcel } from '../services/excelProcessor';
import FileUploader from './FileUploader';
import AssignmentModal from './AssignmentModal';
import Dashboard from './Dashboard';
import { PlayIcon, SpinnerIcon } from './Icons';

declare const saveAs: any;

const AssignerPage: React.FC = () => {
    const [files, setFiles] = useState<ExcelFileState>({
        raw: null,
        info: null,
        duplicate: null,
    });
    const [defenseKeywords, setDefenseKeywords] = useState<string>('Lockheed, Raytheon, Northrop, Bae');
    const [zraxMode, setZraxMode] = useState<'NONE' | 'PRIORITY' | 'ONLY'>('NONE');

    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [isAssigning, setIsAssigning] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [successMessage, setSuccessMessage] = useState<string | null>(null);
    const [processedDataForAssignment, setProcessedDataForAssignment] = useState<any[] | null>(null);
    const [showAssignmentModal, setShowAssignmentModal] = useState<boolean>(false);
    const [pivotData, setPivotData] = useState<{ screener: string; count: number }[] | null>(null);
    const [showDashboard, setShowDashboard] = useState<boolean>(false);


    const handleFileChange = (fileType: keyof ExcelFileState) => (file: File | null) => {
        setFiles(prev => ({ ...prev, [fileType]: file }));
        setError(null);
        setSuccessMessage(null);
    };

    const resetState = () => {
        setFiles({ raw: null, info: null, duplicate: null });
        setProcessedDataForAssignment(null);
        setShowAssignmentModal(false);
        setIsAssigning(false);
        setShowDashboard(false);
        setPivotData(null);
        setError(null);
        setSuccessMessage(null);
        setZraxMode('NONE');
    };

    const handleProcess = useCallback(async () => {
        if (!files.raw || !files.info || !files.duplicate) {
            setError("Please upload all three required Excel files.");
            return;
        }

        setIsLoading(true);
        setError(null);
        setSuccessMessage(null);

        try {
            const processedData = await runInitialProcessing(files.raw, files.info, files.duplicate, defenseKeywords);
            setProcessedDataForAssignment(processedData);
            setShowAssignmentModal(true);
            setSuccessMessage("Step 1 Complete: Data processed. Now assign screeners.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred: ${e.message}`);
            } else {
                setError("An unknown error occurred during processing.");
            }
        } finally {
            setIsLoading(false);
        }
    }, [files, defenseKeywords]);

    const handleFinalizeDownload = async (cnNames: string[], jpNames: string[], specialNames: string[], generalNames: string[]) => {
        if (!processedDataForAssignment) return;

        setIsAssigning(true);
        setError(null);

        try {
            // Pass the zraxMode state to the generation logic
            const { fileData, pivotData } = await assignAndGenerateExcel(
                processedDataForAssignment, 
                cnNames, 
                jpNames, 
                specialNames, 
                generalNames,
                zraxMode
            );

            const blob = new Blob([fileData], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
            saveAs(blob, "Assigned_Report.xlsx");

            setPivotData(pivotData);
            setShowDashboard(true);
            setShowAssignmentModal(false);
            setSuccessMessage("Success! Your download has started. See assignment summary below.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred during assignment: ${e.message}`);
            } else {
                setError("An unknown error occurred during assignment.");
            }
        } finally {
            setIsAssigning(false);
        }
    };

    const handleCancelAssignment = () => {
        setShowAssignmentModal(false);
        setProcessedDataForAssignment(null);
        setSuccessMessage(null);
    };

    const allFilesUploaded = files.raw && files.info && files.duplicate;

    return (
        <>
            <header className="text-center mb-8">
                <h1 className="text-4xl sm:text-5xl font-extrabold mb-2 bg-gradient-to-r from-blue-400 to-purple-500 text-transparent bg-clip-text">
                    TCHUB Assigner
                </h1>
                <p className="text-lg text-gray-400">
                    Automate your data workflow: Process, Assign, and Download.
                </p>
            </header>

            {error && (
                <div className="mb-6 p-4 text-center text-red-300 bg-red-900/50 border border-red-700 rounded-lg">
                    <strong>Error:</strong> {error}
                </div>
            )}
            {successMessage && !showAssignmentModal && (
                <div className="mb-6 p-4 text-center text-green-300 bg-green-900/50 border border-green-700 rounded-lg">
                    {successMessage}
                </div>
            )}

            {showDashboard && pivotData ? (
                 <Dashboard data={pivotData} onReset={resetState} />
            ) : (
                <main className="bg-gray-800/50 backdrop-blur-sm rounded-2xl shadow-2xl p-6 sm:p-8 border border-gray-700">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                        <FileUploader
                            id="raw-data"
                            label="1. Raw Data Sheet"
                            description="Main data to be assigned."
                            onFileSelect={handleFileChange('raw')}
                            fileName={files.raw?.name}
                        />
                        <FileUploader
                            id="info-data"
                            label="2. Information Sheet"
                            description="VLOOKUP 1 (Info) & VLOOKUP 3 (Defense)"
                            onFileSelect={handleFileChange('info')}
                            fileName={files.info?.name}
                        />
                        <FileUploader
                            id="duplicate-data"
                            label="3. Duplicate Data"
                            description="VLOOKUP 2 (Hold Report)"
                            onFileSelect={handleFileChange('duplicate')}
                            fileName={files.duplicate?.name}
                        />
                    </div>

                    <div className="mb-8">
                        <label htmlFor="defense-keywords" className="block text-sm font-medium text-purple-300 mb-2">
                            Defense Keywords (Editable) - Checks extracted value from Info Sheet (Sheet2, Col H)
                        </label>
                        <textarea
                            id="defense-keywords"
                            rows={2}
                            className="w-full bg-gray-900 border border-gray-600 rounded-md p-3 text-white focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition"
                            placeholder="e.g. Lockheed, Raytheon, Northrop, Bae"
                            value={defenseKeywords}
                            onChange={(e) => setDefenseKeywords(e.target.value)}
                        />
                         <p className="mt-1 text-xs text-gray-500">
                            The tool looks for "Sheet2" in File 2. If found, it checks Column H. If not found, it checks Column H of the main info sheet.
                        </p>
                    </div>

                    <div className="flex flex-col items-center justify-center gap-4">
                        <div className="flex items-center gap-4">
                             <button
                                onClick={handleProcess}
                                disabled={!allFilesUploaded || isLoading}
                                className="w-full sm:w-auto inline-flex items-center justify-center px-8 py-4 font-semibold text-lg text-white bg-blue-600 rounded-lg hover:bg-blue-700 disabled:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-4 focus:ring-blue-500/50 transition-all duration-300 ease-in-out shadow-lg transform hover:scale-105"
                            >
                                {isLoading ? (
                                    <>
                                        <SpinnerIcon />
                                        Processing...
                                    </>
                                ) : (
                                    <>
                                        <PlayIcon />
                                        Process Files
                                    </>
                                )}
                            </button>

                            <div className="flex gap-2 bg-gray-900 p-1.5 rounded-lg border border-gray-600">
                                <button 
                                    onClick={() => setZraxMode(prev => prev === 'PRIORITY' ? 'NONE' : 'PRIORITY')}
                                    className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
                                        zraxMode === 'PRIORITY' 
                                            ? 'bg-purple-600 text-white shadow-lg scale-105' 
                                            : 'text-gray-400 hover:text-white hover:bg-gray-800'
                                    }`}
                                    title="ZOP (Priority): Rows with 'ZRAX' in original Column Z will be assigned FIRST."
                                >
                                    ZOP
                                </button>
                                <button 
                                     onClick={() => setZraxMode(prev => prev === 'ONLY' ? 'NONE' : 'ONLY')}
                                     className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
                                        zraxMode === 'ONLY' 
                                            ? 'bg-green-600 text-white shadow-lg scale-105' 
                                            : 'text-gray-400 hover:text-white hover:bg-gray-800'
                                    }`}
                                     title="OZ (Only): ONLY rows with 'ZRAX' in original Column Z will be kept."
                                >
                                    OZ
                                </button>
                            </div>
                        </div>
                        <p className="text-xs text-gray-500 italic">
                            Optional: Click ZOP to prioritize 'ZRAX' items, or OZ to keep only 'ZRAX' items.
                        </p>
                    </div>
                </main>
            )}
             {showAssignmentModal && (
                <AssignmentModal
                    onAssign={handleFinalizeDownload}
                    onCancel={handleCancelAssignment}
                    isAssigning={isAssigning}
                    initialMessage={successMessage}
                />
            )}
        </>
    );
};

export default AssignerPage;

declare const XLSX: any;

// Helper to read a file into an ArrayBuffer using a Promise
const readFileAsArrayBuffer = (file: File): Promise<ArrayBuffer> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as ArrayBuffer);
        reader.onerror = () => reject(reader.error);
        reader.readAsArrayBuffer(file);
    });
};

type Row = any[];

/**
 * Performs the initial data processing: reads files, cleans raw data, and performs multiple VLOOKUPs.
 * Returns the processed data as an array of arrays, ready for the assignment step.
 */
export const runInitialProcessing = async (
    rawFile: File, 
    infoFile: File, 
    dupFile: File, 
    defenseKeywords: string
): Promise<Row[]> => {
    // This function processes the uploaded Excel files.
    // - rawFile: Excel 1 (Main Data)
    // - infoFile: Excel 2 (Contains both Info VLOOKUP and Export/Defense VLOOKUP data)
    // - dupFile: Excel 3 (Duplicate VLOOKUP)

    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded. Please check the script tag in index.html.');
    }

    // 1. Read files into workbooks
    const [rawBuffer, infoBuffer, dupBuffer] = await Promise.all([
        readFileAsArrayBuffer(rawFile),
        readFileAsArrayBuffer(infoFile),
        readFileAsArrayBuffer(dupFile),
    ]);

    const rawWb = XLSX.read(rawBuffer, { type: 'array' });
    const infoWb = XLSX.read(infoBuffer, { type: 'array' });
    const dupWb = XLSX.read(dupBuffer, { type: 'array' });

    // 2. Process Raw Data (Excel 1)
    const rawWs = rawWb.Sheets[rawWb.SheetNames[0]];
    if (!rawWs) throw new Error("Raw Data file is empty or corrupted.");
    let rawData: Row[] = XLSX.utils.sheet_to_json(rawWs, { header: 1, defval: "" });

    // 2.1. Convert Col A to numbers and remove duplicates
    const seen = new Set<number>();
    const uniqueData: Row[] = [];
    const header = rawData.length > 0 ? rawData[0] : [];
    uniqueData.push(header); // Keep header

    for (let i = 1; i < rawData.length; i++) {
        const row = rawData[i];
        const valA = Number(row[0]);
        if (!isNaN(valA) && !seen.has(valA)) {
            seen.add(valA);
            row[0] = valA; // Update row with number type
            uniqueData.push(row);
        }
    }
    rawData = uniqueData;

    // 2.2. Delete columns B, C, D, E, F, G (indices 1 to 6)
    // Mapping:
    // Old Index 0 (A) -> New Index 0
    // Old Index 7 (H) -> New Index 1
    // ...
    // Old Index 19 (T) -> New Index 13
    rawData = rawData.map(row => [row[0], ...row.slice(7)]);

    // 2.3. Rename Col H (now at index 1) to "CTR"
    if (rawData.length > 0 && rawData[0].length > 1) {
        rawData[0][1] = 'CTR';
    }

    // 3. Process Info File (Excel 2)
    // This file now serves two purposes.

    // 3A. Info Lookup Logic
    // Prefer 'Sheet3', else use first sheet.
    let infoSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet3'));
    if (!infoSheetName) infoSheetName = infoWb.SheetNames[0];

    const infoWs = infoWb.Sheets[infoSheetName];
    const infoData: Row[] = XLSX.utils.sheet_to_json(infoWs, { header: 1, defval: "" });

    const infoLookup = new Map<number, any>();
    const infoSeen = new Set<number>();
    for (let i = 1; i < infoData.length; i++) {
        const row = infoData[i];
        const key = Number(row[1]); // Column B
        if (!isNaN(key) && !infoSeen.has(key)) {
            infoSeen.add(key);
            infoLookup.set(key, row[6]); // Column G (Index 6)
        }
    }

    // 3B. Export/Defense Lookup Logic
    // Prefer 'Sheet2'. If not found, use the SAME sheet as Info.
    let exportSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet2'));
    let exportData: Row[];

    if (exportSheetName) {
        const exportWs = infoWb.Sheets[exportSheetName];
        exportData = XLSX.utils.sheet_to_json(exportWs, { header: 1, defval: "" });
    } else {
        // Fallback: Data is on the same sheet (e.g. Sheet3 or whatever was picked for Info)
        exportData = infoData;
    }

    const exportLookup = new Map<number, string>();
    for (let i = 1; i < exportData.length; i++) {
        const row = exportData[i];
        const key = Number(row[1]); // Column B (Index 1) is lookup key
        const value = row[7];       // Column H (Index 7) is return value

        if (!isNaN(key)) {
            exportLookup.set(key, String(value || ""));
        }
    }

    // 4. Process Duplicate File (Excel 3)
    // Formula: =VLOOKUP(A2,'[Master Hold Report .xlsx]Master Hold Report'!$G:$G,1,0)
    const dupSheetName = dupWb.SheetNames.find((name: string) => name.toLowerCase().includes('master hold report')) || dupWb.SheetNames[0];
    const dupWs = dupWb.Sheets[dupSheetName];
    const dupData: Row[] = XLSX.utils.sheet_to_json(dupWs, { header: 1, defval: "" });

    const dupLookup = new Set<number>();
     for (let i = 1; i < dupData.length; i++) {
        const row = dupData[i];
        const key = Number(row[6]); // Column G
        if (!isNaN(key)) {
            dupLookup.add(key);
        }
    }

    // Prepare Keywords
    const keywords = defenseKeywords.split(',').map(k => k.trim().toLowerCase()).filter(k => k.length > 0);

    // 5. Combine data and perform VLOOKUPs on Raw Data (Excel 1)
    const finalData = rawData.map((row, index) => {
        if (index === 0) {
            return [...row, 'Info_VLOOKUP', 'Dup_VLOOKUP', 'Export_Value', 'Defense_Match'];
        }
        const key = row[0];

        // Lookup 1: Info (from File 2, Sheet3/Default, Col G)
        const infoValue = infoLookup.get(key) ?? '#N/A';

        // Lookup 2: Dup (from File 3)
        const dupValue = dupLookup.has(key) ? key : '#N/A';

        // Lookup 3: Export/Defense (from File 2, Sheet2 or Fallback, Col H)
        const exportValueRaw = exportLookup.get(key);
        const exportValue = exportValueRaw !== undefined ? exportValueRaw : '#N/A';

        // Check Keywords
        let isDefenseMatch = false;
        if (exportValueRaw && keywords.length > 0) {
            const valLower = exportValueRaw.toLowerCase();
            isDefenseMatch = keywords.some(kw => valLower.includes(kw));
        }

        return [...row, infoValue, dupValue, exportValue, isDefenseMatch ? 'TRUE' : 'FALSE'];
    });

    return finalData;
};

/**
 * Assigns work, generates the final Excel file, and calculates pivot data.
 * @returns An object containing the .xlsx file data and the pivot table data.
 */
export const assignAndGenerateExcel = async (
    processedData: Row[],
    cnAssignees: string[],
    jpAssignees: string[],
    specialAssignees: string[],
    generalAssignees: string[],
    zraxMode: 'NONE' | 'PRIORITY' | 'ONLY' = 'NONE'
): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {

    const header = processedData.length > 0 ? [...processedData[0]] : [];
    if (processedData.length < 2) {
        const ws = XLSX.utils.aoa_to_sheet([header]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Assigned_Data');
        const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        return { fileData: new Uint8Array(wbout), pivotData: [] };
    }

    const dataRows = processedData.slice(1);

    const dupLookupIndex = header.findIndex((h: string) => h === 'Dup_VLOOKUP');
    if (dupLookupIndex === -1) {
        throw new Error("'Dup_VLOOKUP' column not found. Cannot perform filtering.");
    }

    // 1. Filter rows to keep only those with '#N/A' in 'Dup_VLOOKUP'
    let filteredRows = dataRows.filter(row => row[dupLookupIndex] === '#N/A');

    // 1.5 Apply ZRAX Logic (ZOP / OZ)
    // Original Column T (index 19) becomes index 13 after removing 6 columns (B-G).
    // Logic: row[0] is A. row[1] is H (index 7). row[13] is T (index 19).
    const ZRAX_COLUMN_INDEX = 13;
    const ZRAX_KEYWORD = 'ZRAX';

    if (zraxMode === 'ONLY') {
        // OZ Mode: Keep ONLY rows containing "ZRAX" in original Col T
        filteredRows = filteredRows.filter(row => String(row[ZRAX_COLUMN_INDEX] || '').trim() === ZRAX_KEYWORD);
    } else if (zraxMode === 'PRIORITY') {
        // ZOP Mode: Sort ZRAX rows to the top
        const zraxRows: Row[] = [];
        const otherRows: Row[] = [];
        filteredRows.forEach(row => {
            if (String(row[ZRAX_COLUMN_INDEX] || '').trim() === ZRAX_KEYWORD) {
                zraxRows.push(row);
            } else {
                otherRows.push(row);
            }
        });
        filteredRows = [...zraxRows, ...otherRows];
    }

    const infoLookupIndex = header.findIndex((h: string) => h === 'Info_VLOOKUP');
    if (infoLookupIndex === -1) {
        throw new Error("'Info_VLOOKUP' column not found. Cannot perform assignment.");
    }

    const cnRows: Row[] = [];
    const jpRows: Row[] = [];
    const specialRows: Row[] = [];
    const generalRows: Row[] = [];

    const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY']);

    // 2. Categorize rows based on 'Info_VLOOKUP' value
    // Note: If 'PRIORITY' mode was used, the filteredRows are sorted with ZRAX first.
    // Iterating them in order preserves this sort within each category bucket.
    filteredRows.forEach((row: Row) => {
        const infoValue = row[infoLookupIndex] ? String(row[infoLookupIndex]).toUpperCase() : '';
        if (infoValue.includes('CN')) {
            cnRows.push([...row]);
        } else if (infoValue.includes('JP')) {
            jpRows.push([...row]);
        } else if (Array.from(specialCodes).some(code => infoValue.includes(code))) {
            specialRows.push([...row]);
        } else {
            generalRows.push([...row]);
        }
    });

    // 3. Assign work for each category
    const assignRows = (rows: Row[], assignees: string[], prefix: string) => {
         if (assignees.length > 0) {
            rows.forEach((row, index) => {
                row.unshift(assignees[index % assignees.length]);
            });
        } else {
            rows.forEach(row => row.unshift(`UNASSIGNED_${prefix}`));
        }
    }

    assignRows(cnRows, cnAssignees, 'CN');
    assignRows(jpRows, jpAssignees, 'JP');
    assignRows(specialRows, specialAssignees, 'SPECIAL');
    assignRows(generalRows, generalAssignees, 'GENERAL');

    // 4. Combine all assigned rows
    const finalAssignedRows = [...cnRows, ...jpRows, ...specialRows, ...generalRows];

    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });

    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({
        screener,
        count
    })).sort((a, b) => a.screener.localeCompare(b.screener));

    // 5. Prepare final sheet

    // 5.1. Find and remove the 'CTR' column
    const ctrIndex = header.findIndex((h: string) => h === 'CTR');
    if (ctrIndex !== -1) {
        header.splice(ctrIndex, 1);
        finalAssignedRows.forEach(row => {
            row.splice(ctrIndex + 1, 1); // +1 because we added 'Screener' at start conceptually
        });
    }

    // 5.2. Prepend 'Screener' to the modified header
    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];

    // 5.3. Create worksheet and apply header styling
    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);

    const headerStyle = {
        font: { bold: true },
        fill: { fgColor: { rgb: "FFD3D3D3" } }
    };

    const range = XLSX.utils.decode_range(finalWs['!ref']);
    if (range && range.e.r >= 0) { 
        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellAddress = XLSX.utils.encode_cell({ r: 0, c: C });
            const cell = finalWs[cellAddress];
            if (cell) {
                cell.s = headerStyle;
            }
        }
    }

    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'Assigned_Data');

    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    const fileData = new Uint8Array(wbout);

    return { fileData, pivotData };
};

export const processColumnA = async (file: File): Promise<{ uniqueNumbers: number[] }> => {
    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded.');
    }

    const buffer = await readFileAsArrayBuffer(file);
    const wb = XLSX.read(buffer, { type: 'array' });
    const ws = wb.Sheets[wb.SheetNames[0]];
    if (!ws) throw new Error("File is empty or corrupted.");

    const data: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });

    const seen = new Set<number>();
    for (let i = 0; i < data.length; i++) {
        const row = data[i];
        if (row && row.length > 0 && row[0] !== null) {
            const valA = Number(row[0]);
            if (!isNaN(valA)) {
                seen.add(valA);
            }
        }
    }

    return { uniqueNumbers: Array.from(seen).sort((a, b) => a - b) };
};

import React, { useState, useCallback } from 'react';
import type { ExcelFileState } from '../types';
import { runInitialProcessing, assignAndGenerateExcel } from '../services/excelProcessor';
import FileUploader from './FileUploader';
import AssignmentModal from './AssignmentModal';
import Dashboard from './Dashboard';
import { PlayIcon, SpinnerIcon } from './Icons';

declare const saveAs: any;

const AssignerPage: React.FC = () => {
    const [files, setFiles] = useState<ExcelFileState>({
        raw: null,
        info: null,
        duplicate: null,
    });
    const [defenseKeywords, setDefenseKeywords] = useState<string>('Lockheed, Raytheon, Northrop, Bae');
    const [zraxMode, setZraxMode] = useState<'NONE' | 'PRIORITY' | 'ONLY'>('NONE');

    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [isAssigning, setIsAssigning] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [successMessage, setSuccessMessage] = useState<string | null>(null);
    const [processedDataForAssignment, setProcessedDataForAssignment] = useState<any[] | null>(null);
    const [showAssignmentModal, setShowAssignmentModal] = useState<boolean>(false);
    const [pivotData, setPivotData] = useState<{ screener: string; count: number }[] | null>(null);
    const [showDashboard, setShowDashboard] = useState<boolean>(false);


    const handleFileChange = (fileType: keyof ExcelFileState) => (file: File | null) => {
        setFiles(prev => ({ ...prev, [fileType]: file }));
        setError(null);
        setSuccessMessage(null);
    };

    const resetState = () => {
        setFiles({ raw: null, info: null, duplicate: null });
        setProcessedDataForAssignment(null);
        setShowAssignmentModal(false);
        setIsAssigning(false);
        setShowDashboard(false);
        setPivotData(null);
        setError(null);
        setSuccessMessage(null);
        setZraxMode('NONE');
    };

    const handleProcess = useCallback(async () => {
        if (!files.raw || !files.info || !files.duplicate) {
            setError("Please upload all three required Excel files.");
            return;
        }

        setIsLoading(true);
        setError(null);
        setSuccessMessage(null);

        try {
            const processedData = await runInitialProcessing(files.raw, files.info, files.duplicate, defenseKeywords);
            setProcessedDataForAssignment(processedData);
            setShowAssignmentModal(true);
            setSuccessMessage("Step 1 Complete: Data processed. Now assign screeners.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred: ${e.message}`);
            } else {
                setError("An unknown error occurred during processing.");
            }
        } finally {
            setIsLoading(false);
        }
    }, [files, defenseKeywords]);

    const handleFinalizeDownload = async (cnNames: string[], jpNames: string[], specialNames: string[], generalNames: string[]) => {
        if (!processedDataForAssignment) return;

        setIsAssigning(true);
        setError(null);

        try {
            // Pass the zraxMode state to the generation logic
            const { fileData, pivotData } = await assignAndGenerateExcel(
                processedDataForAssignment, 
                cnNames, 
                jpNames, 
                specialNames, 
                generalNames,
                zraxMode
            );

            const blob = new Blob([fileData], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
            saveAs(blob, "Assigned_Report.xlsx");

            setPivotData(pivotData);
            setShowDashboard(true);
            setShowAssignmentModal(false);
            setSuccessMessage("Success! Your download has started. See assignment summary below.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred during assignment: ${e.message}`);
            } else {
                setError("An unknown error occurred during assignment.");
            }
        } finally {
            setIsAssigning(false);
        }
    };

    const handleCancelAssignment = () => {
        setShowAssignmentModal(false);
        setProcessedDataForAssignment(null);
        setSuccessMessage(null);
    };

    const allFilesUploaded = files.raw && files.info && files.duplicate;

    return (
        <>
            <header className="text-center mb-8">
                <h1 className="text-4xl sm:text-5xl font-extrabold mb-2 bg-gradient-to-r from-blue-400 to-purple-500 text-transparent bg-clip-text">
                    TCHUB Assigner
                </h1>
                <p className="text-lg text-gray-400">
                    Automate your data workflow: Process, Assign, and Download.
                </p>
            </header>

            {error && (
                <div className="mb-6 p-4 text-center text-red-300 bg-red-900/50 border border-red-700 rounded-lg">
                    <strong>Error:</strong> {error}
                </div>
            )}
            {successMessage && !showAssignmentModal && (
                <div className="mb-6 p-4 text-center text-green-300 bg-green-900/50 border border-green-700 rounded-lg">
                    {successMessage}
                </div>
            )}

            {showDashboard && pivotData ? (
                 <Dashboard data={pivotData} onReset={resetState} />
            ) : (
                <main className="bg-gray-800/50 backdrop-blur-sm rounded-2xl shadow-2xl p-6 sm:p-8 border border-gray-700">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                        <FileUploader
                            id="raw-data"
                            label="1. Raw Data Sheet"
                            description="Main data to be assigned."
                            onFileSelect={handleFileChange('raw')}
                            fileName={files.raw?.name}
                        />
                        <FileUploader
                            id="info-data"
                            label="2. Information Sheet"
                            description="VLOOKUP 1 (Info) & VLOOKUP 3 (Defense)"
                            onFileSelect={handleFileChange('info')}
                            fileName={files.info?.name}
                        />
                        <FileUploader
                            id="duplicate-data"
                            label="3. Duplicate Data"
                            description="VLOOKUP 2 (Hold Report)"
                            onFileSelect={handleFileChange('duplicate')}
                            fileName={files.duplicate?.name}
                        />
                    </div>

                    <div className="mb-8">
                        <label htmlFor="defense-keywords" className="block text-sm font-medium text-purple-300 mb-2">
                            Defense Keywords (Editable) - Checks extracted value from Info Sheet (Sheet2, Col H)
                        </label>
                        <textarea
                            id="defense-keywords"
                            rows={2}
                            className="w-full bg-gray-900 border border-gray-600 rounded-md p-3 text-white focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition"
                            placeholder="e.g. Lockheed, Raytheon, Northrop, Bae"
                            value={defenseKeywords}
                            onChange={(e) => setDefenseKeywords(e.target.value)}
                        />
                         <p className="mt-1 text-xs text-gray-500">
                            The tool looks for "Sheet2" in File 2. If found, it checks Column H. If not found, it checks Column H of the main info sheet.
                        </p>
                    </div>

                    <div className="flex flex-col items-center justify-center gap-4">
                        <div className="flex items-center gap-4">
                             <button
                                onClick={handleProcess}
                                disabled={!allFilesUploaded || isLoading}
                                className="w-full sm:w-auto inline-flex items-center justify-center px-8 py-4 font-semibold text-lg text-white bg-blue-600 rounded-lg hover:bg-blue-700 disabled:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-4 focus:ring-blue-500/50 transition-all duration-300 ease-in-out shadow-lg transform hover:scale-105"
                            >
                                {isLoading ? (
                                    <>
                                        <SpinnerIcon />
                                        Processing...
                                    </>
                                ) : (
                                    <>
                                        <PlayIcon />
                                        Process Files
                                    </>
                                )}
                            </button>

                            <div className="flex gap-2 bg-gray-900 p-1.5 rounded-lg border border-gray-600">
                                <button 
                                    onClick={() => setZraxMode(prev => prev === 'PRIORITY' ? 'NONE' : 'PRIORITY')}
                                    className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
                                        zraxMode === 'PRIORITY' 
                                            ? 'bg-purple-600 text-white shadow-lg scale-105' 
                                            : 'text-gray-400 hover:text-white hover:bg-gray-800'
                                    }`}
                                    title="ZOP (Priority): Rows with 'ZRAX' in original Column T will be assigned FIRST."
                                >
                                    ZOP
                                </button>
                                <button 
                                     onClick={() => setZraxMode(prev => prev === 'ONLY' ? 'NONE' : 'ONLY')}
                                     className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
                                        zraxMode === 'ONLY' 
                                            ? 'bg-green-600 text-white shadow-lg scale-105' 
                                            : 'text-gray-400 hover:text-white hover:bg-gray-800'
                                    }`}
                                     title="OZ (Only): ONLY rows with 'ZRAX' in original Column T will be kept."
                                >
                                    OZ
                                </button>
                            </div>
                        </div>
                        <p className="text-xs text-gray-500 italic">
                            Optional: Click ZOP to prioritize 'ZRAX' (in Col T) items, or OZ to keep only 'ZRAX' items.
                        </p>
                    </div>
                </main>
            )}
             {showAssignmentModal && (
                <AssignmentModal
                    onAssign={handleFinalizeDownload}
                    onCancel={handleCancelAssignment}
                    isAssigning={isAssigning}
                    initialMessage={successMessage}
                />
            )}
        </>
    );
};

export default AssignerPage;

declare const XLSX: any;

// Helper to read a file into an ArrayBuffer using a Promise
const readFileAsArrayBuffer = (file: File): Promise<ArrayBuffer> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as ArrayBuffer);
        reader.onerror = () => reject(reader.error);
        reader.readAsArrayBuffer(file);
    });
};

type Row = any[];

/**
 * Performs the initial data processing: reads files, cleans raw data, and performs multiple VLOOKUPs.
 * Returns the processed data as an array of arrays, ready for the assignment step.
 */
export const runInitialProcessing = async (
    rawFile: File, 
    infoFile: File, 
    dupFile: File, 
    defenseKeywords: string
): Promise<Row[]> => {
    // This function processes the uploaded Excel files.
    // - rawFile: Excel 1 (Main Data)
    // - infoFile: Excel 2 (Contains both Info VLOOKUP and Export/Defense VLOOKUP data)
    // - dupFile: Excel 3 (Duplicate VLOOKUP)

    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded. Please check the script tag in index.html.');
    }

    // 1. Read files into workbooks
    const [rawBuffer, infoBuffer, dupBuffer] = await Promise.all([
        readFileAsArrayBuffer(rawFile),
        readFileAsArrayBuffer(infoFile),
        readFileAsArrayBuffer(dupFile),
    ]);

    const rawWb = XLSX.read(rawBuffer, { type: 'array' });
    const infoWb = XLSX.read(infoBuffer, { type: 'array' });
    const dupWb = XLSX.read(dupBuffer, { type: 'array' });

    // 2. Process Raw Data (Excel 1)
    const rawWs = rawWb.Sheets[rawWb.SheetNames[0]];
    if (!rawWs) throw new Error("Raw Data file is empty or corrupted.");
    let rawData: Row[] = XLSX.utils.sheet_to_json(rawWs, { header: 1, defval: "" });

    // 2.1. Convert Col A to numbers and remove duplicates
    const seen = new Set<number>();
    const uniqueData: Row[] = [];
    const header = rawData.length > 0 ? rawData[0] : [];
    uniqueData.push(header); // Keep header

    for (let i = 1; i < rawData.length; i++) {
        const row = rawData[i];
        const valA = Number(row[0]);
        if (!isNaN(valA) && !seen.has(valA)) {
            seen.add(valA);
            row[0] = valA; // Update row with number type
            uniqueData.push(row);
        }
    }
    rawData = uniqueData;

    // 2.2. Delete columns B, C, D, E, F, G (indices 1 to 6)
    // Mapping:
    // Old Index 0 (A) -> New Index 0
    // Old Index 7 (H) -> New Index 1
    // ...
    // Old Index 18 (S) -> New Index 12
    rawData = rawData.map(row => [row[0], ...row.slice(7)]);

    // 2.3. Rename Col H (now at index 1) to "CTR"
    if (rawData.length > 0 && rawData[0].length > 1) {
        rawData[0][1] = 'CTR';
    }

    // 3. Process Info File (Excel 2)
    // This file now serves two purposes.

    // 3A. Info Lookup Logic
    // Prefer 'Sheet3', else use first sheet.
    let infoSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet3'));
    if (!infoSheetName) infoSheetName = infoWb.SheetNames[0];

    const infoWs = infoWb.Sheets[infoSheetName];
    const infoData: Row[] = XLSX.utils.sheet_to_json(infoWs, { header: 1, defval: "" });

    const infoLookup = new Map<number, any>();
    const infoSeen = new Set<number>();
    for (let i = 1; i < infoData.length; i++) {
        const row = infoData[i];
        const key = Number(row[1]); // Column B
        if (!isNaN(key) && !infoSeen.has(key)) {
            infoSeen.add(key);
            infoLookup.set(key, row[6]); // Column G (Index 6)
        }
    }

    // 3B. Export/Defense Lookup Logic
    // Prefer 'Sheet2'. If not found, use the SAME sheet as Info.
    let exportSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet2'));
    let exportData: Row[];

    if (exportSheetName) {
        const exportWs = infoWb.Sheets[exportSheetName];
        exportData = XLSX.utils.sheet_to_json(exportWs, { header: 1, defval: "" });
    } else {
        // Fallback: Data is on the same sheet (e.g. Sheet3 or whatever was picked for Info)
        exportData = infoData;
    }

    const exportLookup = new Map<number, string>();
    for (let i = 1; i < exportData.length; i++) {
        const row = exportData[i];
        const key = Number(row[1]); // Column B (Index 1) is lookup key
        const value = row[7];       // Column H (Index 7) is return value

        if (!isNaN(key)) {
            exportLookup.set(key, String(value || ""));
        }
    }

    // 4. Process Duplicate File (Excel 3)
    // Formula: =VLOOKUP(A2,'[Master Hold Report .xlsx]Master Hold Report'!$G:$G,1,0)
    const dupSheetName = dupWb.SheetNames.find((name: string) => name.toLowerCase().includes('master hold report')) || dupWb.SheetNames[0];
    const dupWs = dupWb.Sheets[dupSheetName];
    const dupData: Row[] = XLSX.utils.sheet_to_json(dupWs, { header: 1, defval: "" });

    const dupLookup = new Set<number>();
     for (let i = 1; i < dupData.length; i++) {
        const row = dupData[i];
        const key = Number(row[6]); // Column G
        if (!isNaN(key)) {
            dupLookup.add(key);
        }
    }

    // Prepare Keywords
    const keywords = defenseKeywords.split(',').map(k => k.trim().toLowerCase()).filter(k => k.length > 0);

    // 5. Combine data and perform VLOOKUPs on Raw Data (Excel 1)
    const finalData = rawData.map((row, index) => {
        if (index === 0) {
            return [...row, 'Info_VLOOKUP', 'Dup_VLOOKUP', 'Export_Value', 'Defense_Match'];
        }
        const key = row[0];

        // Lookup 1: Info (from File 2, Sheet3/Default, Col G)
        const infoValue = infoLookup.get(key) ?? '#N/A';

        // Lookup 2: Dup (from File 3)
        const dupValue = dupLookup.has(key) ? key : '#N/A';

        // Lookup 3: Export/Defense (from File 2, Sheet2 or Fallback, Col H)
        const exportValueRaw = exportLookup.get(key);
        const exportValue = exportValueRaw !== undefined ? exportValueRaw : '#N/A';

        // Check Keywords
        let isDefenseMatch = false;
        if (exportValueRaw && keywords.length > 0) {
            const valLower = exportValueRaw.toLowerCase();
            isDefenseMatch = keywords.some(kw => valLower.includes(kw));
        }

        return [...row, infoValue, dupValue, exportValue, isDefenseMatch ? 'TRUE' : 'FALSE'];
    });

    return finalData;
};

/**
 * Assigns work, generates the final Excel file, and calculates pivot data.
 * @returns An object containing the .xlsx file data and the pivot table data.
 */
export const assignAndGenerateExcel = async (
    processedData: Row[],
    cnAssignees: string[],
    jpAssignees: string[],
    specialAssignees: string[],
    generalAssignees: string[],
    zraxMode: 'NONE' | 'PRIORITY' | 'ONLY' = 'NONE'
): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {

    const header = processedData.length > 0 ? [...processedData[0]] : [];
    if (processedData.length < 2) {
        const ws = XLSX.utils.aoa_to_sheet([header]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Assigned_Data');
        const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        return { fileData: new Uint8Array(wbout), pivotData: [] };
    }

    const dataRows = processedData.slice(1);

    const dupLookupIndex = header.findIndex((h: string) => h === 'Dup_VLOOKUP');
    if (dupLookupIndex === -1) {
        throw new Error("'Dup_VLOOKUP' column not found. Cannot perform filtering.");
    }

    // 1. Filter rows to keep only those with '#N/A' in 'Dup_VLOOKUP'
    let filteredRows = dataRows.filter(row => row[dupLookupIndex] === '#N/A');

    // 1.5 Apply ZRAX Logic (ZOP / OZ)
    // Original Column S (index 18) becomes index 12 after removing 6 columns (B-G).
    // Logic: row[0] is A. row[1] is H (index 7). row[12] is S (index 18).
    const ZRAX_COLUMN_INDEX = 12;
    const ZRAX_KEYWORD = 'ZRAX';

    if (zraxMode === 'ONLY') {
        // OZ Mode: Keep ONLY rows containing "ZRAX" in original Col S
        filteredRows = filteredRows.filter(row => String(row[ZRAX_COLUMN_INDEX] || '').trim() === ZRAX_KEYWORD);
    } else if (zraxMode === 'PRIORITY') {
        // ZOP Mode: Sort ZRAX rows to the top
        const zraxRows: Row[] = [];
        const otherRows: Row[] = [];
        filteredRows.forEach(row => {
            if (String(row[ZRAX_COLUMN_INDEX] || '').trim() === ZRAX_KEYWORD) {
                zraxRows.push(row);
            } else {
                otherRows.push(row);
            }
        });
        filteredRows = [...zraxRows, ...otherRows];
    }

    const infoLookupIndex = header.findIndex((h: string) => h === 'Info_VLOOKUP');
    if (infoLookupIndex === -1) {
        throw new Error("'Info_VLOOKUP' column not found. Cannot perform assignment.");
    }

    const cnRows: Row[] = [];
    const jpRows: Row[] = [];
    const specialRows: Row[] = [];
    const generalRows: Row[] = [];

    const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY']);

    // 2. Categorize rows based on 'Info_VLOOKUP' value
    // Note: If 'PRIORITY' mode was used, the filteredRows are sorted with ZRAX first.
    // Iterating them in order preserves this sort within each category bucket.
    filteredRows.forEach((row: Row) => {
        const infoValue = row[infoLookupIndex] ? String(row[infoLookupIndex]).toUpperCase() : '';
        if (infoValue.includes('CN')) {
            cnRows.push([...row]);
        } else if (infoValue.includes('JP')) {
            jpRows.push([...row]);
        } else if (Array.from(specialCodes).some(code => infoValue.includes(code))) {
            specialRows.push([...row]);
        } else {
            generalRows.push([...row]);
        }
    });

    // 3. Assign work for each category
    const assignRows = (rows: Row[], assignees: string[], prefix: string) => {
         if (assignees.length > 0) {
            rows.forEach((row, index) => {
                row.unshift(assignees[index % assignees.length]);
            });
        } else {
            rows.forEach(row => row.unshift(`UNASSIGNED_${prefix}`));
        }
    }

    assignRows(cnRows, cnAssignees, 'CN');
    assignRows(jpRows, jpAssignees, 'JP');
    assignRows(specialRows, specialAssignees, 'SPECIAL');
    assignRows(generalRows, generalAssignees, 'GENERAL');

    // 4. Combine all assigned rows
    const finalAssignedRows = [...cnRows, ...jpRows, ...specialRows, ...generalRows];

    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });

    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({
        screener,
        count
    })).sort((a, b) => a.screener.localeCompare(b.screener));

    // 5. Prepare final sheet

    // 5.1. Find and remove the 'CTR' column
    const ctrIndex = header.findIndex((h: string) => h === 'CTR');
    if (ctrIndex !== -1) {
        header.splice(ctrIndex, 1);
        finalAssignedRows.forEach(row => {
            row.splice(ctrIndex + 1, 1); // +1 because we added 'Screener' at start conceptually
        });
    }

    // 5.2. Prepend 'Screener' to the modified header
    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];

    // 5.3. Create worksheet and apply header styling
    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);

    const headerStyle = {
        font: { bold: true },
        fill: { fgColor: { rgb: "FFD3D3D3" } }
    };

    const range = XLSX.utils.decode_range(finalWs['!ref']);
    if (range && range.e.r >= 0) { 
        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellAddress = XLSX.utils.encode_cell({ r: 0, c: C });
            const cell = finalWs[cellAddress];
            if (cell) {
                cell.s = headerStyle;
            }
        }
    }

    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'Assigned_Data');

    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    const fileData = new Uint8Array(wbout);

    return { fileData, pivotData };
};

export const processColumnA = async (file: File): Promise<{ uniqueNumbers: number[] }> => {
    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded.');
    }

    const buffer = await readFileAsArrayBuffer(file);
    const wb = XLSX.read(buffer, { type: 'array' });
    const ws = wb.Sheets[wb.SheetNames[0]];
    if (!ws) throw new Error("File is empty or corrupted.");

    const data: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });

    const seen = new Set<number>();
    for (let i = 0; i < data.length; i++) {
        const row = data[i];
        if (row && row.length > 0 && row[0] !== null) {
            const valA = Number(row[0]);
            if (!isNaN(valA)) {
                seen.add(valA);
            }
        }
    }

    return { uniqueNumbers: Array.from(seen).sort((a, b) => a - b) };
};

import React, { useState, useCallback } from 'react';
import type { ExcelFileState } from '../types';
import { runInitialProcessing, assignAndGenerateExcel } from '../services/excelProcessor';
import FileUploader from './FileUploader';
import AssignmentModal from './AssignmentModal';
import Dashboard from './Dashboard';
import { PlayIcon, SpinnerIcon } from './Icons';

declare const saveAs: any;

const AssignerPage: React.FC = () => {
    const [files, setFiles] = useState<ExcelFileState>({
        raw: null,
        info: null,
        duplicate: null,
    });
    const [defenseKeywords, setDefenseKeywords] = useState<string>('Lockheed, Raytheon, Northrop, Bae');
    const [zraxMode, setZraxMode] = useState<'NONE' | 'PRIORITY' | 'ONLY'>('NONE');

    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [isAssigning, setIsAssigning] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [successMessage, setSuccessMessage] = useState<string | null>(null);
    const [processedDataForAssignment, setProcessedDataForAssignment] = useState<any[] | null>(null);
    const [showAssignmentModal, setShowAssignmentModal] = useState<boolean>(false);
    const [pivotData, setPivotData] = useState<{ screener: string; count: number }[] | null>(null);
    const [showDashboard, setShowDashboard] = useState<boolean>(false);


    const handleFileChange = (fileType: keyof ExcelFileState) => (file: File | null) => {
        setFiles(prev => ({ ...prev, [fileType]: file }));
        setError(null);
        setSuccessMessage(null);
    };

    const resetState = () => {
        setFiles({ raw: null, info: null, duplicate: null });
        setProcessedDataForAssignment(null);
        setShowAssignmentModal(false);
        setIsAssigning(false);
        setShowDashboard(false);
        setPivotData(null);
        setError(null);
        setSuccessMessage(null);
        setZraxMode('NONE');
    };

    const handleProcess = useCallback(async () => {
        if (!files.raw || !files.info || !files.duplicate) {
            setError("Please upload all three required Excel files.");
            return;
        }

        setIsLoading(true);
        setError(null);
        setSuccessMessage(null);

        try {
            const processedData = await runInitialProcessing(files.raw, files.info, files.duplicate, defenseKeywords);
            setProcessedDataForAssignment(processedData);
            setShowAssignmentModal(true);
            setSuccessMessage("Step 1 Complete: Data processed. Now assign screeners.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred: ${e.message}`);
            } else {
                setError("An unknown error occurred during processing.");
            }
        } finally {
            setIsLoading(false);
        }
    }, [files, defenseKeywords]);

    const handleFinalizeDownload = async (cnNames: string[], jpNames: string[], specialNames: string[], generalNames: string[]) => {
        if (!processedDataForAssignment) return;

        setIsAssigning(true);
        setError(null);

        try {
            // Pass the zraxMode state to the generation logic
            const { fileData, pivotData } = await assignAndGenerateExcel(
                processedDataForAssignment, 
                cnNames, 
                jpNames, 
                specialNames, 
                generalNames,
                zraxMode
            );

            const blob = new Blob([fileData], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
            saveAs(blob, "Assigned_Report.xlsx");

            setPivotData(pivotData);
            setShowDashboard(true);
            setShowAssignmentModal(false);
            setSuccessMessage("Success! Your download has started. See assignment summary below.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred during assignment: ${e.message}`);
            } else {
                setError("An unknown error occurred during assignment.");
            }
        } finally {
            setIsAssigning(false);
        }
    };

    const handleCancelAssignment = () => {
        setShowAssignmentModal(false);
        setProcessedDataForAssignment(null);
        setSuccessMessage(null);
    };

    const allFilesUploaded = files.raw && files.info && files.duplicate;

    return (
        <>
            <header className="text-center mb-8">
                <h1 className="text-4xl sm:text-5xl font-extrabold mb-2 bg-gradient-to-r from-blue-400 to-purple-500 text-transparent bg-clip-text">
                    TCHUB Assigner
                </h1>
                <p className="text-lg text-gray-400">
                    Automate your data workflow: Process, Assign, and Download.
                </p>
            </header>

            {error && (
                <div className="mb-6 p-4 text-center text-red-300 bg-red-900/50 border border-red-700 rounded-lg">
                    <strong>Error:</strong> {error}
                </div>
            )}
            {successMessage && !showAssignmentModal && (
                <div className="mb-6 p-4 text-center text-green-300 bg-green-900/50 border border-green-700 rounded-lg">
                    {successMessage}
                </div>
            )}

            {showDashboard && pivotData ? (
                 <Dashboard data={pivotData} onReset={resetState} />
            ) : (
                <main className="bg-gray-800/50 backdrop-blur-sm rounded-2xl shadow-2xl p-6 sm:p-8 border border-gray-700">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                        <FileUploader
                            id="raw-data"
                            label="1. Raw Data Sheet"
                            description="Main data to be assigned."
                            onFileSelect={handleFileChange('raw')}
                            fileName={files.raw?.name}
                        />
                        <FileUploader
                            id="info-data"
                            label="2. Information Sheet"
                            description="VLOOKUP 1 (Info) & VLOOKUP 3 (Defense)"
                            onFileSelect={handleFileChange('info')}
                            fileName={files.info?.name}
                        />
                        <FileUploader
                            id="duplicate-data"
                            label="3. Duplicate Data"
                            description="VLOOKUP 2 (Hold Report)"
                            onFileSelect={handleFileChange('duplicate')}
                            fileName={files.duplicate?.name}
                        />
                    </div>

                    <div className="mb-8">
                        <label htmlFor="defense-keywords" className="block text-sm font-medium text-purple-300 mb-2">
                            Defense Keywords (Editable) - Checks extracted value from Info Sheet (Sheet2, Col H)
                        </label>
                        <textarea
                            id="defense-keywords"
                            rows={2}
                            className="w-full bg-gray-900 border border-gray-600 rounded-md p-3 text-white focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition"
                            placeholder="e.g. Lockheed, Raytheon, Northrop, Bae"
                            value={defenseKeywords}
                            onChange={(e) => setDefenseKeywords(e.target.value)}
                        />
                         <p className="mt-1 text-xs text-gray-500">
                            The tool looks for "Sheet2" in File 2. If found, it checks Column H. If not found, it checks Column H of the main info sheet.
                        </p>
                    </div>

                    <div className="flex flex-col items-center justify-center gap-4">
                        <div className="flex items-center gap-4">
                             <button
                                onClick={handleProcess}
                                disabled={!allFilesUploaded || isLoading}
                                className="w-full sm:w-auto inline-flex items-center justify-center px-8 py-4 font-semibold text-lg text-white bg-blue-600 rounded-lg hover:bg-blue-700 disabled:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-4 focus:ring-blue-500/50 transition-all duration-300 ease-in-out shadow-lg transform hover:scale-105"
                            >
                                {isLoading ? (
                                    <>
                                        <SpinnerIcon />
                                        Processing...
                                    </>
                                ) : (
                                    <>
                                        <PlayIcon />
                                        Process Files
                                    </>
                                )}
                            </button>

                            <div className="flex gap-2 bg-gray-900 p-1.5 rounded-lg border border-gray-600">
                                <button 
                                    onClick={() => setZraxMode(prev => prev === 'PRIORITY' ? 'NONE' : 'PRIORITY')}
                                    className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
                                        zraxMode === 'PRIORITY' 
                                            ? 'bg-purple-600 text-white shadow-lg scale-105' 
                                            : 'text-gray-400 hover:text-white hover:bg-gray-800'
                                    }`}
                                    title="ZOP (Priority): Rows with 'ZRAX' in original Column S will be assigned FIRST."
                                >
                                    ZOP
                                </button>
                                <button 
                                     onClick={() => setZraxMode(prev => prev === 'ONLY' ? 'NONE' : 'ONLY')}
                                     className={`px-3 py-1.5 text-xs font-bold rounded transition-all ${
                                        zraxMode === 'ONLY' 
                                            ? 'bg-green-600 text-white shadow-lg scale-105' 
                                            : 'text-gray-400 hover:text-white hover:bg-gray-800'
                                    }`}
                                     title="OZ (Only): ONLY rows with 'ZRAX' in original Column S will be kept."
                                >
                                    OZ
                                </button>
                            </div>
                        </div>
                        <p className="text-xs text-gray-500 italic">
                            Optional: Click ZOP to prioritize 'ZRAX' (in Col S) items, or OZ to keep only 'ZRAX' items.
                        </p>
                    </div>
                </main>
            )}
             {showAssignmentModal && (
                <AssignmentModal
                    onAssign={handleFinalizeDownload}
                    onCancel={handleCancelAssignment}
                    isAssigning={isAssigning}
                    initialMessage={successMessage}
                />
            )}
        </>
    );
};

export default AssignerPage;

declare const XLSX: any;

// Helper to read a file into an ArrayBuffer using a Promise
const readFileAsArrayBuffer = (file: File): Promise<ArrayBuffer> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as ArrayBuffer);
        reader.onerror = () => reject(reader.error);
        reader.readAsArrayBuffer(file);
    });
};

type Row = any[];
type ZraxFilter = 'NONE' | 'ZOP' | 'OZ';

/**
 * Performs the initial data processing: reads files, cleans raw data, and performs VLOOKUPs.
 * Returns the processed data as an array of arrays, ready for the assignment step.
 */
export const runInitialProcessing = async (
    rawFile: File, 
    infoFile: File, 
    dupFile: File, 
    zraxFilter: ZraxFilter,
    defenseKeywords: string
): Promise<Row[]> => {
    // This function processes the three uploaded Excel files.
    // - rawFile: Corresponds to "Excel 1", the main data sheet.
    // - infoFile: Corresponds to "Excel 2", the information sheet (Sheet3 for Info, Sheet2 for Export/Defense).
    // - dupFile: Corresponds to "Excel 3", the duplicate data for the second VLOOKUP.

    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded. Please check the script tag in index.html.');
    }

    // 1. Read all files into workbooks
    const [rawBuffer, infoBuffer, dupBuffer] = await Promise.all([
        readFileAsArrayBuffer(rawFile),
        readFileAsArrayBuffer(infoFile),
        readFileAsArrayBuffer(dupFile),
    ]);

    const rawWb = XLSX.read(rawBuffer, { type: 'array' });
    const infoWb = XLSX.read(infoBuffer, { type: 'array' });
    const dupWb = XLSX.read(dupBuffer, { type: 'array' });

    // 2. Process Raw Data (Excel 1)
    const rawWs = rawWb.Sheets[rawWb.SheetNames[0]];
    if (!rawWs) throw new Error("Raw Data file is empty or corrupted.");
    let rawData: Row[] = XLSX.utils.sheet_to_json(rawWs, { header: 1, defval: "" });

    // 2.1. Apply "Only ZRAX" (OZ) filter if selected
    // Note: This pre-filter logic might need to be consistent with the post-processing index.
    // However, if we filter here, we must use the original index.
    // Original Column S is index 18.
    if (zraxFilter === 'OZ') {
        const headerRow = rawData.length > 0 ? rawData[0] : [];
        const dataRows = rawData.length > 1 ? rawData.slice(1) : [];
        // Original Column S is at index 18
        const zraxOnlyData = dataRows.filter(row => String(row[18]).trim() === 'ZRAX');
        rawData = [headerRow, ...zraxOnlyData];
    }

    // 2.2. Convert Col A to numbers and remove duplicates
    const seen = new Set<number>();
    const uniqueData: Row[] = [];
    const header = rawData.length > 0 ? rawData[0] : [];
    uniqueData.push(header); // Keep header

    for (let i = 1; i < rawData.length; i++) {
        const row = rawData[i];
        const valA = Number(row[0]);
        if (!isNaN(valA) && !seen.has(valA)) {
            seen.add(valA);
            row[0] = valA; // Update row with number type
            uniqueData.push(row);
        }
    }
    rawData = uniqueData;

    // 2.3. Delete columns B, C, D, E, F, G (indices 1 to 6)
    rawData = rawData.map(row => [row[0], ...row.slice(7)]);

    // 2.4. Rename Col H (now at index 1) to "CTR"
    if (rawData.length > 0 && rawData[0].length > 1) {
        rawData[0][1] = 'CTR';
    }

    // 3. Process Info File (Excel 2)

    // 3A. Info Lookup Logic (Existing)
    // Formula: =VLOOKUP(A2,'[Excel 2.xlsx]Sheet3'!$B:$H,6,0)
    const infoSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet3')) || infoWb.SheetNames[0];
    const infoWs = infoWb.Sheets[infoSheetName];
    const infoData: Row[] = XLSX.utils.sheet_to_json(infoWs, { header: 1, defval: "" });

    const infoLookup = new Map<number, any>();
    const infoSeen = new Set<number>();
    for (let i = 1; i < infoData.length; i++) {
        const row = infoData[i];
        const key = Number(row[1]); // Column B
        if (!isNaN(key) && !infoSeen.has(key)) {
            infoSeen.add(key);
            infoLookup.set(key, row[6]); // Column G
        }
    }

    // 3B. Export/Defense Lookup Logic (NEW)
    // Formula: =VLOOKUP(A2,'[...xlsx]Sheet2'!B:H,7,0)
    // Checks 'Sheet2'. Falls back to Info sheet if not found, but prefers Sheet2.
    let exportSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet2'));
    if (!exportSheetName) exportSheetName = infoSheetName; // Fallback

    const exportWs = infoWb.Sheets[exportSheetName];
    // Re-read data if sheet is different, else reuse logic? Safer to read again.
    const exportData: Row[] = XLSX.utils.sheet_to_json(exportWs, { header: 1, defval: "" });
    const exportLookup = new Map<number, string>();

    for (let i = 1; i < exportData.length; i++) {
        const row = exportData[i];
        const key = Number(row[1]); // Column B (Index 1) is lookup key (First col of B:H)
        const value = row[7];       // Column H (Index 7) is return value (7th col of B:H)

        if (!isNaN(key)) {
            exportLookup.set(key, String(value || ""));
        }
    }

    // 4. Process Duplicate File (Excel 3)
    const dupSheetName = dupWb.SheetNames.find((name: string) => name.toLowerCase().includes('master hold report')) || dupWb.SheetNames[0];
    const dupWs = dupWb.Sheets[dupSheetName];
    const dupData: Row[] = XLSX.utils.sheet_to_json(dupWs, { header: 1, defval: "" });

    const dupLookup = new Set<number>();
     for (let i = 1; i < dupData.length; i++) {
        const row = dupData[i];
        const key = Number(row[6]); // Column G
        if (!isNaN(key)) {
            dupLookup.add(key);
        }
    }

    // Prepare Keywords
    const keywords = defenseKeywords.split(',').map(k => k.trim().toLowerCase()).filter(k => k.length > 0);

    // 5. Combine data
    const finalData = rawData.map((row, index) => {
        // Add headers to the first row
        if (index === 0) {
            return [...row, 'Info_VLOOKUP', 'Dup_VLOOKUP', 'Export_Value', 'Defense_Match'];
        }

        const key = row[0];

        // Lookup 1: Info
        const infoValue = infoLookup.get(key) ?? '#N/A';

        // Lookup 2: Dup
        const dupValue = dupLookup.has(key) ? key : '#N/A'; 

        // Lookup 3: Export/Defense
        const exportValue = exportLookup.get(key) ?? '#N/A';

        // Check Keywords
        let isDefenseMatch = 'FALSE';
        if (exportValue !== '#N/A' && keywords.length > 0) {
            const valLower = exportValue.toLowerCase();
            if (keywords.some(kw => valLower.includes(kw))) {
                isDefenseMatch = 'TRUE';
            }
        }

        return [...row, infoValue, dupValue, exportValue, isDefenseMatch];
    });

    return finalData;
};

/**
 * Assigns work, generates the final Excel file, and calculates pivot data.
 * @returns An object containing the .xlsx file data and the pivot table data.
 */
export const assignAndGenerateExcel = async (
    processedData: Row[],
    cnAssignees: string[],
    jpAssignees: string[],
    specialAssignees: string[],
    generalAssignees: string[],
    zraxFilter: ZraxFilter
): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {

    // Create a deep copy of the header to avoid mutation issues
    const header = processedData.length > 0 ? [...processedData[0]] : [];
    if (processedData.length < 2) { // Only header or empty
        const ws = XLSX.utils.aoa_to_sheet([header]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Assigned_Data');
        const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        return { fileData: new Uint8Array(wbout), pivotData: [] };
    }

    const dataRows = processedData.slice(1);

    const dupLookupIndex = header.findIndex((h: string) => h === 'Dup_VLOOKUP');
    if (dupLookupIndex === -1) {
        throw new Error("'Dup_VLOOKUP' column not found. Cannot perform filtering.");
    }

    // 1. Filter rows to keep only those with '#N/A' in 'Dup_VLOOKUP'
    const filteredRows = dataRows.filter(row => row[dupLookupIndex] === '#N/A');

    // Helper function to categorize and assign a given set of rows
    const processAndAssign = (rowsToAssign: Row[]): Row[] => {
        const infoLookupIndex = header.findIndex((h: string) => h === 'Info_VLOOKUP');
        if (infoLookupIndex === -1) throw new Error("'Info_VLOOKUP' column not found.");

        const cnRows: Row[] = [], jpRows: Row[] = [], specialRows: Row[] = [], generalRows: Row[] = [];
        const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY', 'CU', 'IR', 'KP', 'SY']);

        rowsToAssign.forEach((row: Row) => {
            const infoValue = row[infoLookupIndex] ? String(row[infoLookupIndex]).toUpperCase() : '';
            if (infoValue.includes('CN')) cnRows.push([...row]);
            else if (infoValue.includes('JP')) jpRows.push([...row]);
            else if (Array.from(specialCodes).some(code => infoValue.includes(code))) specialRows.push([...row]);
            else generalRows.push([...row]);
        });

        if (cnAssignees.length > 0) cnRows.forEach((row, index) => row.unshift(cnAssignees[index % cnAssignees.length]));
        else cnRows.forEach(row => row.unshift('UNASSIGNED_CN'));

        if (jpAssignees.length > 0) jpRows.forEach((row, index) => row.unshift(jpAssignees[index % jpAssignees.length]));
        else jpRows.forEach(row => row.unshift('UNASSIGNED_JP'));

        if (specialAssignees.length > 0) specialRows.forEach((row, index) => row.unshift(specialAssignees[index % specialAssignees.length]));
        else specialRows.forEach(row => row.unshift('UNASSIGNED_SPECIAL'));

        if (generalAssignees.length > 0) generalRows.forEach((row, index) => row.unshift(generalAssignees[index % generalAssignees.length]));
        else generalRows.forEach(row => row.unshift('UNASSIGNED_GENERAL'));

        return [...cnRows, ...jpRows, ...specialRows, ...generalRows];
    };

    let finalAssignedRows: Row[];

    if (zraxFilter === 'ZOP') {
        // Original Col S (Index 18) becomes Index 12 after removing 6 columns (B-G).
        const zColIndex = 12; 
        const zraxRows: Row[] = [];
        const otherRows: Row[] = [];

        filteredRows.forEach(row => {
            // Ensure the row has enough columns to prevent errors
            if (row.length > zColIndex && String(row[zColIndex]).trim() === 'ZRAX') {
                zraxRows.push(row);
            } else {
                otherRows.push(row);
            }
        });

        const assignedZrax = processAndAssign(zraxRows);
        const assignedOthers = processAndAssign(otherRows);
        finalAssignedRows = [...assignedZrax, ...assignedOthers];
    } else {
        finalAssignedRows = processAndAssign(filteredRows);
    }

    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });

    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({
        screener,
        count
    })).sort((a, b) => a.screener.localeCompare(b.screener));

    // 5. Prepare final sheet for download

    // 5.1. Find and remove the 'CTR' column
    const ctrIndex = header.findIndex((h: string) => h === 'CTR');
    if (ctrIndex !== -1) {
        // Remove from the original header array
        header.splice(ctrIndex, 1);

        // Remove from each assigned data row. The original columns are shifted by 1 due to 'Screener'
        finalAssignedRows.forEach(row => {
            row.splice(ctrIndex + 1, 1);
        });
    }

    // 5.2. Prepend 'Screener' to the modified header
    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];

    // 5.3. Create worksheet and apply header styling
    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);

    const headerStyle = {
        font: { bold: true, color: { rgb: "FFFFFFFF" } },
        fill: { patternType: "solid", fgColor: { rgb: "FF4F46E5" } } // Blue background to match UI
    };

    const range = XLSX.utils.decode_range(finalWs['!ref']);
    if (range && range.e.r >= 0) { // Check if there's at least one row (the header)
        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellAddress = XLSX.utils.encode_cell({ r: 0, c: C });
            const cell = finalWs[cellAddress];
            if (cell) {
                cell.s = headerStyle;
            }
        }
    }

    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'Assigned_Data');

    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    const fileData = new Uint8Array(wbout);

    return { fileData, pivotData };
};

/**
 * Processes a single Excel file to extract unique numbers from Column A.
 */
export const processColumnA = async (file: File): Promise<{ uniqueNumbers: number[] }> => {
    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded.');
    }

    const buffer = await readFileAsArrayBuffer(file);
    const wb = XLSX.read(buffer, { type: 'array' });
    const ws = wb.Sheets[wb.SheetNames[0]];
    if (!ws) throw new Error("File is empty or corrupted.");

    const data: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });

    const seen = new Set<number>();
    // Iterate through all rows, starting from the first row
    for (let i = 0; i < data.length; i++) {
        const row = data[i];
        // Ensure row and cell exist before processing
        if (row && row.length > 0 && row[0] !== null) {
            const valA = Number(row[0]);
            // Check if the conversion to number is successful
            if (!isNaN(valA)) {
                seen.add(valA);
            }
        }
    }

    return { uniqueNumbers: Array.from(seen).sort((a, b) => a - b) };
};

import React, { useState, useCallback } from 'react';
import type { ExcelFileState } from '../types';
import { runInitialProcessing, assignAndGenerateExcel } from '../services/excelProcessor';
import FileUploader from './FileUploader';
import AssignmentModal from './AssignmentModal';
import Dashboard from './Dashboard';
import { PlayIcon, SpinnerIcon } from './Icons';

declare const saveAs: any;

const AssignerPage: React.FC = () => {
    const [files, setFiles] = useState<ExcelFileState>({
        raw: null,
        info: null,
        duplicate: null,
    });
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [isAssigning, setIsAssigning] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [successMessage, setSuccessMessage] = useState<string | null>(null);
    const [processedDataForAssignment, setProcessedDataForAssignment] = useState<any[] | null>(null);
    const [showAssignmentModal, setShowAssignmentModal] = useState<boolean>(false);
    const [pivotData, setPivotData] = useState<{ screener: string; count: number }[] | null>(null);
    const [showDashboard, setShowDashboard] = useState<boolean>(false);
    const [zraxFilter, setZraxFilter] = useState<'NONE' | 'ZOP' | 'OZ'>('NONE');
    const [defenseKeywords, setDefenseKeywords] = useState<string>('Lockheed, Raytheon, Northrop, Bae');

    const handleFileChange = (fileType: keyof ExcelFileState) => (file: File | null) => {
        setFiles(prev => ({ ...prev, [fileType]: file }));
        setError(null);
        setSuccessMessage(null);
    };

    const resetState = () => {
        setFiles({ raw: null, info: null, duplicate: null });
        setProcessedDataForAssignment(null);
        setShowAssignmentModal(false);
        setIsAssigning(false);
        setShowDashboard(false);
        setPivotData(null);
        setError(null);
        setSuccessMessage(null);
        setZraxFilter('NONE');
    };

    const handleProcess = useCallback(async () => {
        if (!files.raw || !files.info || !files.duplicate) {
            setError("Please upload all three required Excel files.");
            return;
        }

        setIsLoading(true);
        setError(null);
        setSuccessMessage(null);

        try {
            const processedData = await runInitialProcessing(files.raw, files.info, files.duplicate, zraxFilter, defenseKeywords);
            setProcessedDataForAssignment(processedData);
            setShowAssignmentModal(true);
            setSuccessMessage("Step 1 Complete: Data processed. Now assign screeners.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred: ${e.message}`);
            } else {
                setError("An unknown error occurred during processing.");
            }
        } finally {
            setIsLoading(false);
        }
    }, [files, zraxFilter, defenseKeywords]);

    const handleFinalizeDownload = async (cnNames: string[], jpNames: string[], specialNames: string[], generalNames: string[]) => {
        if (!processedDataForAssignment) return;

        setIsAssigning(true);
        setError(null);

        try {
            const { fileData, pivotData } = await assignAndGenerateExcel(processedDataForAssignment, cnNames, jpNames, specialNames, generalNames, zraxFilter);
            const blob = new Blob([fileData], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
            saveAs(blob, "Assigned_Report.xlsx");

            setPivotData(pivotData);
            setShowDashboard(true);
            setShowAssignmentModal(false);
            setSuccessMessage("Success! Your download has started. See assignment summary below.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred during assignment: ${e.message}`);
            } else {
                setError("An unknown error occurred during assignment.");
            }
             // Keep modal open on error to allow retry
        } finally {
            setIsAssigning(false);
        }
    };

    const handleCancelAssignment = () => {
        setShowAssignmentModal(false);
        setProcessedDataForAssignment(null);
        setSuccessMessage(null);
    };

    const handleZraxFilterChange = (filter: 'ZOP' | 'OZ') => {
        setZraxFilter(prev => (prev === filter ? 'NONE' : filter));
    };

    const getFilterButtonClasses = (filter: 'ZOP' | 'OZ') => `
        px-3 py-1 text-xs font-bold rounded-full transition-colors duration-200 border-2 
