declare const XLSX: any;

// Helper to read a file into an ArrayBuffer using a Promise
const readFileAsArrayBuffer = (file: File): Promise<ArrayBuffer> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as ArrayBuffer);
        reader.onerror = () => reject(reader.error);
        reader.readAsArrayBuffer(file);
    });
};

type Row = any[];
type ZraxFilter = 'NONE' | 'ZOP' | 'OZ';

/**
 * Performs the initial data processing: reads files, cleans raw data, and performs VLOOKUPs.
 * Returns the processed data as an array of arrays, ready for the assignment step.
 */
export const runInitialProcessing = async (
    rawFile: File, 
    infoFile: File, 
    dupFile: File, 
    zraxFilter: ZraxFilter,
    defenseKeywords: string
): Promise<Row[]> => {
    // This function processes the three uploaded Excel files.
    // - rawFile: Corresponds to "Excel 1", the main data sheet.
    // - infoFile: Corresponds to "Excel 2", the information sheet (Sheet3 for Info, Sheet2 for Export/Defense).
    // - dupFile: Corresponds to "Excel 3", the duplicate data for the second VLOOKUP.

    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded. Please check the script tag in index.html.');
    }

    // 1. Read all files into workbooks
    const [rawBuffer, infoBuffer, dupBuffer] = await Promise.all([
        readFileAsArrayBuffer(rawFile),
        readFileAsArrayBuffer(infoFile),
        readFileAsArrayBuffer(dupFile),
    ]);

    const rawWb = XLSX.read(rawBuffer, { type: 'array' });
    const infoWb = XLSX.read(infoBuffer, { type: 'array' });
    const dupWb = XLSX.read(dupBuffer, { type: 'array' });

    // 2. Process Raw Data (Excel 1)
    const rawWs = rawWb.Sheets[rawWb.SheetNames[0]];
    if (!rawWs) throw new Error("Raw Data file is empty or corrupted.");
    let rawData: Row[] = XLSX.utils.sheet_to_json(rawWs, { header: 1, defval: "" });

    // 2.1. Apply "Only ZRAX" (OZ) filter if selected
    // Note: This pre-filter logic applies to the RAW data before column removal.
    // User Requirement: Check Column Z (Index 25) for 'ZRAX'.
    if (zraxFilter === 'OZ') {
        const headerRow = rawData.length > 0 ? rawData[0] : [];
        const dataRows = rawData.length > 1 ? rawData.slice(1) : [];
        // Original Column Z is at index 25 (0-based)
        const zraxOnlyData = dataRows.filter(row => String(row[25]).trim() === 'ZRAX');
        rawData = [headerRow, ...zraxOnlyData];
    }

    // 2.2. Convert Col A to numbers and remove duplicates
    const seen = new Set<number>();
    const uniqueData: Row[] = [];
    const header = rawData.length > 0 ? rawData[0] : [];
    uniqueData.push(header); // Keep header

    for (let i = 1; i < rawData.length; i++) {
        const row = rawData[i];
        const valA = Number(row[0]);
        if (!isNaN(valA) && !seen.has(valA)) {
            seen.add(valA);
            row[0] = valA; // Update row with number type
            uniqueData.push(row);
        }
    }
    rawData = uniqueData;

    // 2.3. Delete columns B through H (indices 1 to 7)
    // Keep Index 0 (A). Skip 1-7 (B-H). Keep 8+ (I...).
    rawData = rawData.map(row => [row[0], ...row.slice(8)]);

    // 2.4. Rename Col I (now at index 1) to "CTR" if applicable
    if (rawData.length > 0 && rawData[0].length > 1) {
        rawData[0][1] = 'CTR';
    }

    // 3. Process Info File (Excel 2)

    // 3A. Info Lookup Logic (Existing)
    // Formula: =VLOOKUP(A2,'[Excel 2.xlsx]Sheet3'!$B:$H,6,0)
    const infoSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet3')) || infoWb.SheetNames[0];
    const infoWs = infoWb.Sheets[infoSheetName];
    const infoData: Row[] = XLSX.utils.sheet_to_json(infoWs, { header: 1, defval: "" });

    const infoLookup = new Map<number, any>();
    const infoSeen = new Set<number>();
    for (let i = 1; i < infoData.length; i++) {
        const row = infoData[i];
        const key = Number(row[1]); // Column B
        if (!isNaN(key) && !infoSeen.has(key)) {
            infoSeen.add(key);
            infoLookup.set(key, row[6]); // Column G
        }
    }

    // 3B. Export/Defense Lookup Logic (NEW)
    // Formula: =VLOOKUP(A2,'[...xlsx]Sheet2'!B:H,7,0)
    // Checks 'Sheet2'. Falls back to Info sheet if not found, but prefers Sheet2.
    let exportSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet2'));
    if (!exportSheetName) exportSheetName = infoSheetName; // Fallback

    const exportWs = infoWb.Sheets[exportSheetName];
    // Re-read data if sheet is different, else reuse logic? Safer to read again.
    const exportData: Row[] = XLSX.utils.sheet_to_json(exportWs, { header: 1, defval: "" });
    const exportLookup = new Map<number, string>();

    for (let i = 1; i < exportData.length; i++) {
        const row = exportData[i];
        const key = Number(row[1]); // Column B (Index 1) is lookup key (First col of B:H)
        const value = row[7];       // Column H (Index 7) is return value (7th col of B:H)

        if (!isNaN(key)) {
            exportLookup.set(key, String(value || ""));
        }
    }

    // 4. Process Duplicate File (Excel 3)
    const dupSheetName = dupWb.SheetNames.find((name: string) => name.toLowerCase().includes('master hold report')) || dupWb.SheetNames[0];
    const dupWs = dupWb.Sheets[dupSheetName];
    const dupData: Row[] = XLSX.utils.sheet_to_json(dupWs, { header: 1, defval: "" });

    const dupLookup = new Set<number>();
     for (let i = 1; i < dupData.length; i++) {
        const row = dupData[i];
        const key = Number(row[6]); // Column G
        if (!isNaN(key)) {
            dupLookup.add(key);
        }
    }

    // Prepare Keywords
    const keywords = defenseKeywords.split(',').map(k => k.trim().toLowerCase()).filter(k => k.length > 0);

    // 5. Combine data
    const finalData = rawData.map((row, index) => {
        // Add headers to the first row
        if (index === 0) {
            return [...row, 'Info_VLOOKUP', 'Dup_VLOOKUP', 'Export_Value', 'Defense_Match'];
        }

        const key = row[0];

        // Lookup 1: Info
        const infoValue = infoLookup.get(key) ?? '#N/A';

        // Lookup 2: Dup
        const dupValue = dupLookup.has(key) ? key : '#N/A'; 

        // Lookup 3: Export/Defense
        const exportValue = exportLookup.get(key) ?? '#N/A';

        // Check Keywords
        let isDefenseMatch = 'FALSE';
        if (exportValue !== '#N/A' && keywords.length > 0) {
            const valLower = exportValue.toLowerCase();
            if (keywords.some(kw => valLower.includes(kw))) {
                isDefenseMatch = 'TRUE';
            }
        }

        return [...row, infoValue, dupValue, exportValue, isDefenseMatch];
    });

    return finalData;
};

/**
 * Assigns work, generates the final Excel file, and calculates pivot data.
 * @returns An object containing the .xlsx file data and the pivot table data.
 */
export const assignAndGenerateExcel = async (
    processedData: Row[],
    cnAssignees: string[],
    jpAssignees: string[],
    specialAssignees: string[],
    generalAssignees: string[],
    zraxFilter: ZraxFilter
): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {

    // Create a deep copy of the header to avoid mutation issues
    const header = processedData.length > 0 ? [...processedData[0]] : [];
    if (processedData.length < 2) { // Only header or empty
        const ws = XLSX.utils.aoa_to_sheet([header]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Assigned_Data');
        const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        return { fileData: new Uint8Array(wbout), pivotData: [] };
    }

    const dataRows = processedData.slice(1);

    const dupLookupIndex = header.findIndex((h: string) => h === 'Dup_VLOOKUP');
    if (dupLookupIndex === -1) {
        throw new Error("'Dup_VLOOKUP' column not found. Cannot perform filtering.");
    }

    // 1. Filter rows to keep only those with '#N/A' in 'Dup_VLOOKUP'
    const filteredRows = dataRows.filter(row => row[dupLookupIndex] === '#N/A');

    // Helper function to categorize and assign a given set of rows
    const processAndAssign = (rowsToAssign: Row[]): Row[] => {
        const infoLookupIndex = header.findIndex((h: string) => h === 'Info_VLOOKUP');
        if (infoLookupIndex === -1) throw new Error("'Info_VLOOKUP' column not found.");

        const cnRows: Row[] = [], jpRows: Row[] = [], specialRows: Row[] = [], generalRows: Row[] = [];
        const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY', 'CU', 'IR', 'KP', 'SY']);

        rowsToAssign.forEach((row: Row) => {
            const infoValue = row[infoLookupIndex] ? String(row[infoLookupIndex]).toUpperCase() : '';
            if (infoValue.includes('CN')) cnRows.push([...row]);
            else if (infoValue.includes('JP')) jpRows.push([...row]);
            else if (Array.from(specialCodes).some(code => infoValue.includes(code))) specialRows.push([...row]);
            else generalRows.push([...row]);
        });

        if (cnAssignees.length > 0) cnRows.forEach((row, index) => row.unshift(cnAssignees[index % cnAssignees.length]));
        else cnRows.forEach(row => row.unshift('UNASSIGNED_CN'));

        if (jpAssignees.length > 0) jpRows.forEach((row, index) => row.unshift(jpAssignees[index % jpAssignees.length]));
        else jpRows.forEach(row => row.unshift('UNASSIGNED_JP'));

        if (specialAssignees.length > 0) specialRows.forEach((row, index) => row.unshift(specialAssignees[index % specialAssignees.length]));
        else specialRows.forEach(row => row.unshift('UNASSIGNED_SPECIAL'));

        if (generalAssignees.length > 0) generalRows.forEach((row, index) => row.unshift(generalAssignees[index % generalAssignees.length]));
        else generalRows.forEach(row => row.unshift('UNASSIGNED_GENERAL'));

        return [...cnRows, ...jpRows, ...specialRows, ...generalRows];
    };

    let finalAssignedRows: Row[];

    if (zraxFilter === 'ZOP') {
        const zColIndex = 18; 
        const zraxRows: Row[] = [];
        const otherRows: Row[] = [];

        filteredRows.forEach(row => {
            if (row.length > zColIndex && String(row[zColIndex]).trim() === 'ZRAX') {
                zraxRows.push(row);
            } else {
                otherRows.push(row);
            }
        });

        const assignedZrax = processAndAssign(zraxRows);
        const assignedOthers = processAndAssign(otherRows);
        finalAssignedRows = [...assignedZrax, ...assignedOthers];
    } else {
        finalAssignedRows = processAndAssign(filteredRows);
    }

    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });

    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({
        screener,
        count
    })).sort((a, b) => a.screener.localeCompare(b.screener));

    const ctrIndex = header.findIndex((h: string) => h === 'CTR');
    if (ctrIndex !== -1) {
        header.splice(ctrIndex, 1);
        finalAssignedRows.forEach(row => {
            row.splice(ctrIndex + 1, 1);
        });
    }

    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];

    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);

    const headerStyle = {
        font: { bold: true, color: { rgb: "FFFFFFFF" } },
        fill: { patternType: "solid", fgColor: { rgb: "FF4F46E5" } } 
    };

    const range = XLSX.utils.decode_range(finalWs['!ref']);
    if (range && range.e.r >= 0) { 
        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellAddress = XLSX.utils.encode_cell({ r: 0, c: C });
            const cell = finalWs[cellAddress];
            if (cell) {
                cell.s = headerStyle;
            }
        }
    }

    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'Assigned_Data');

    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    const fileData = new Uint8Array(wbout);

    return { fileData, pivotData };
};

/**
 * Processes GGP Orders data.
 * 1. Removes specific header rows (1,2,3,4,6). Keeps row 5 as header and 7+ as data.
 * 2. Removes Column A (blank) and deduplicates based on the NEW Column A.
 * 3. Filters rows using VLOOKUP against Master Hold Report (Col G).
 */
export const processGGPData = async (rawFile: File, holdFile: File): Promise<Row[]> => {
    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded.');
    }

    const [rawBuffer, holdBuffer] = await Promise.all([
        readFileAsArrayBuffer(rawFile),
        readFileAsArrayBuffer(holdFile)
    ]);
    const rawWb = XLSX.read(rawBuffer, { type: 'array' });
    const holdWb = XLSX.read(holdBuffer, { type: 'array' });

    // 1. Process Raw Data
    const rawWs = rawWb.Sheets[rawWb.SheetNames[0]];
    // Read all rows including empty ones to preserve index mapping for removal
    const rawDataFull: Row[] = XLSX.utils.sheet_to_json(rawWs, { header: 1, defval: "" });

    // Row Removal Logic:
    // Remove Row 1, 2, 3, 4, 6 (Indices 0, 1, 2, 3, 5).
    // Keep Row 5 (Index 4) -> This is the Header.
    // Keep Row 7+ (Indices 6+) -> This is the Data.
    let cleanedRows: Row[] = [];

    if (rawDataFull.length > 4) {
        // Push Header (Row 5 / Index 4)
        cleanedRows.push(rawDataFull[4]);
    }
    if (rawDataFull.length > 6) {
        // Push Data (Row 7+ / Index 6+)
        cleanedRows = cleanedRows.concat(rawDataFull.slice(6));
    }

    if (cleanedRows.length === 0) throw new Error("Processed data is empty after row removal.");

    // 2. Remove Column A (Index 0) and Deduplicate
    // The "Blank" Column A is removed. The old Column B becomes Index 0.
    const seen = new Set<string>();
    const dedupedRows: Row[] = [];

    // Header
    const header = cleanedRows[0].slice(1);
    dedupedRows.push(header);

    for (let i = 1; i < cleanedRows.length; i++) {
        const row = cleanedRows[i];
        // Slice(1) to remove Column A
        const newRow = row.slice(1);

        // Use new Col A (Index 0) for deduping
        // Ensure we check if it has content? The requirement says "Remove duplicates from A column".
        // We convert to string to ensure uniqueness.
        const key = newRow.length > 0 ? String(newRow[0]) : "";

        // Simple check to skip completely empty rows if key is empty?
        // Let's strictly deduplicate.
        if (!seen.has(key)) {
            seen.add(key);
            dedupedRows.push(newRow);
        }
    }

    // 3. VLOOKUP Filter
    // Lookup Key: New Col A (Index 0).
    // Lookup Range: Master Hold Report Col G (Index 6).
    // Logic: If Key exists in Master Hold Col G, remove the row. (Keep only #N/A)
    const holdWs = holdWb.Sheets[holdWb.SheetNames[0]];
    const holdData: Row[] = XLSX.utils.sheet_to_json(holdWs, { header: 1, defval: "" });
    const holdSet = new Set<string>();

    // Build set from Col G (Index 6)
    holdData.forEach(r => {
        if (r.length > 6) {
             holdSet.add(String(r[6]));
        }
    });

    // Filter
    const finalRows: Row[] = [dedupedRows[0]]; // Keep Header
    for (let i = 1; i < dedupedRows.length; i++) {
        const row = dedupedRows[i];
        const key = row.length > 0 ? String(row[0]) : "";

        if (!holdSet.has(key)) {
            finalRows.push(row);
        }
    }

    return finalRows;
};

/**
 * Assigns GGP Data based on Country code in Column R.
 * Column R in original file is Index 17 (0=A..17=R).
 * Since we removed Col A (Index 0), the old R is now Index 16.
 * 
 * Supports two groups:
 * 1. Special (High Risk): RU, VE, NI, BY, UA, CU, IR, KP, SY
 * 2. General: Everything else
 */
export const assignGGPData = async (
    processedData: Row[],
    specialAssignees: string[],
    generalAssignees: string[]
): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {

    const header = processedData.length > 0 ? [...processedData[0]] : [];
    const dataRows = processedData.slice(1);

    // Logic for assignment based on Column R (Old R = Index 17).
    // New Index = 17 - 1 = 16.
    const countryColIndex = 16;

    const specialRows: Row[] = [];
    const generalRows: Row[] = [];
    const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY', 'CU', 'IR', 'KP', 'SY']);

    dataRows.forEach((row: Row) => {
        // Safety check for row length
        const countryVal = (row.length > countryColIndex && row[countryColIndex]) 
            ? String(row[countryColIndex]).toUpperCase() 
            : '';

        if (Array.from(specialCodes).some(code => countryVal.includes(code))) {
            specialRows.push([...row]);
        } else {
            generalRows.push([...row]);
        }
    });

    // Distribute
    if (specialAssignees.length > 0) specialRows.forEach((row, index) => row.unshift(specialAssignees[index % specialAssignees.length]));
    else specialRows.forEach(row => row.unshift('UNASSIGNED_SPECIAL'));

    if (generalAssignees.length > 0) generalRows.forEach((row, index) => row.unshift(generalAssignees[index % generalAssignees.length]));
    else generalRows.forEach(row => row.unshift('UNASSIGNED_GENERAL'));

    const finalAssignedRows = [...specialRows, ...generalRows];

    // Pivot Data
    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });

    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({
        screener,
        count
    })).sort((a, b) => a.screener.localeCompare(b.screener));

    // Final Sheet Creation
    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];
    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);

    const headerStyle = {
        font: { bold: true, color: { rgb: "FFFFFFFF" } },
        fill: { patternType: "solid", fgColor: { rgb: "FF4F46E5" } } 
    };

    const range = XLSX.utils.decode_range(finalWs['!ref']);
    if (range && range.e.r >= 0) { 
        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellAddress = XLSX.utils.encode_cell({ r: 0, c: C });
            const cell = finalWs[cellAddress];
            if (cell) {
                cell.s = headerStyle;
            }
        }
    }

    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'GGP_Assigned');

    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    const fileData = new Uint8Array(wbout);

    return { fileData, pivotData };
};

/**
 * Processes a single Excel file to extract unique numbers from Column A.
 */
export const processColumnA = async (file: File): Promise<{ uniqueNumbers: number[] }> => {
    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded.');
    }

    const buffer = await readFileAsArrayBuffer(file);
    const wb = XLSX.read(buffer, { type: 'array' });
    const ws = wb.Sheets[wb.SheetNames[0]];
    if (!ws) throw new Error("File is empty or corrupted.");

    const data: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });

    const seen = new Set<number>();
    // Iterate through all rows, starting from the first row
    for (let i = 0; i < data.length; i++) {
        const row = data[i];
        // Ensure row and cell exist before processing
        if (row && row.length > 0 && row[0] !== null) {
            const valA = Number(row[0]);
            // Check if the conversion to number is successful
            if (!isNaN(valA)) {
                seen.add(valA);
            }
        }
    }

    return { uniqueNumbers: Array.from(seen).sort((a, b) => a - b) };
};

import React, { useState } from 'react';
import type { GGPFileState } from '../types';
import { processGGPData, assignGGPData } from '../services/excelProcessor';
import FileUploader from './FileUploader';
import AssignmentModal from './AssignmentModal';
import Dashboard from './Dashboard';
import { PlayIcon, SpinnerIcon } from './Icons';

declare const saveAs: any;

const GGPPage: React.FC = () => {
    const [files, setFiles] = useState<GGPFileState>({
        raw: null,
        hold: null,
    });
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [isAssigning, setIsAssigning] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [successMessage, setSuccessMessage] = useState<string | null>(null);
    const [processedData, setProcessedData] = useState<any[] | null>(null);
    const [showAssignmentModal, setShowAssignmentModal] = useState<boolean>(false);
    const [pivotData, setPivotData] = useState<{ screener: string; count: number }[] | null>(null);
    const [showDashboard, setShowDashboard] = useState<boolean>(false);

    const handleFileChange = (fileType: keyof GGPFileState) => (file: File | null) => {
        setFiles(prev => ({ ...prev, [fileType]: file }));
        setError(null);
        setSuccessMessage(null);
    };

    const resetState = () => {
        setFiles({ raw: null, hold: null });
        setProcessedData(null);
        setShowAssignmentModal(false);
        setIsAssigning(false);
        setShowDashboard(false);
        setPivotData(null);
        setError(null);
        setSuccessMessage(null);
    };

    const handleProcess = async () => {
        if (!files.raw || !files.hold) {
            setError("Please upload both required Excel files.");
            return;
        }

        setIsLoading(true);
        setError(null);
        setSuccessMessage(null);

        try {
            const data = await processGGPData(files.raw, files.hold);
            setProcessedData(data);
            setShowAssignmentModal(true);
            setSuccessMessage("Data processed successfully. Please assign screeners.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`Processing Error: ${e.message}`);
            } else {
                setError("An unknown error occurred during processing.");
            }
        } finally {
            setIsLoading(false);
        }
    };

    const handleFinalizeDownload = async (cnNames: string[], jpNames: string[], specialNames: string[], generalNames: string[]) => {
        if (!processedData) return;

        setIsAssigning(true);
        setError(null);

        try {
            // Note: cnNames and jpNames are ignored/empty for GGP assignments as per new requirement.
            const { fileData, pivotData } = await assignGGPData(processedData, specialNames, generalNames);
            const blob = new Blob([fileData], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
            saveAs(blob, "GGP_Assigned_Orders.xlsx");

            setPivotData(pivotData);
            setShowDashboard(true);
            setShowAssignmentModal(false);
            setSuccessMessage("Assignment complete. File downloaded.");
        } catch (e) {
             if (e instanceof Error) {
                setError(`Assignment Error: ${e.message}`);
            } else {
                setError("An unknown error occurred during assignment.");
            }
        } finally {
            setIsAssigning(false);
        }
    };

    return (
        <>
             <header className="text-center mb-8">
                <h1 className="text-4xl sm:text-5xl font-extrabold mb-2 bg-gradient-to-r from-green-400 to-blue-500 text-transparent bg-clip-text">
                    GGP Order Assigner
                </h1>
                <p className="text-lg text-gray-400">
                    Clean, Filter, and Assign GGP Orders efficiently.
                </p>
            </header>

            {error && (
                <div className="mb-6 p-4 text-center text-red-300 bg-red-900/50 border border-red-700 rounded-lg">
                    <strong>Error:</strong> {error}
                </div>
            )}
             {successMessage && !showAssignmentModal && (
                <div className="mb-6 p-4 text-center text-green-300 bg-green-900/50 border border-green-700 rounded-lg">
                    {successMessage}
                </div>
            )}

            {showDashboard && pivotData ? (
                <Dashboard data={pivotData} onReset={resetState} />
            ) : (
                <main className="bg-gray-800/50 backdrop-blur-sm rounded-2xl shadow-2xl p-6 sm:p-8 border border-gray-700">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8 max-w-4xl mx-auto">
                        <FileUploader
                            id="ggp-raw"
                            label="1. GGP Raw Excel"
                            description="Upload the raw order file (.xlsx or .xls)."
                            onFileSelect={handleFileChange('raw')}
                            fileName={files.raw?.name}
                        />
                        <FileUploader
                            id="ggp-hold"
                            label="2. Master Hold Report"
                            description="Used to filter duplicates (VLOOKUP)."
                            onFileSelect={handleFileChange('hold')}
                            fileName={files.hold?.name}
                        />
                    </div>

                    <div className="mt-8 text-center">
                        <button
                            onClick={handleProcess}
                            disabled={!files.raw || !files.hold || isLoading}
                            className="w-full sm:w-auto inline-flex items-center justify-center px-8 py-4 font-semibold text-lg text-white bg-green-600 rounded-lg hover:bg-green-700 disabled:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-4 focus:ring-green-500/50 transition-all duration-300 ease-in-out shadow-lg transform hover:scale-105"
                        >
                             {isLoading ? (
                                <>
                                    <SpinnerIcon />
                                    Processing...
                                </>
                            ) : (
                                <>
                                    <PlayIcon />
                                    Process & Assign
                                </>
                            )}
                        </button>
                    </div>
                </main>
            )}

            {showAssignmentModal && (
                <AssignmentModal
                    onAssign={handleFinalizeDownload}
                    onCancel={() => setShowAssignmentModal(false)}
                    isAssigning={isAssigning}
                    initialMessage={successMessage}
                    variant="ggp"
                />
            )}
        </>
    );
};

export default GGPPage;

declare const XLSX: any;

// Helper to read a file into an ArrayBuffer using a Promise
const readFileAsArrayBuffer = (file: File): Promise<ArrayBuffer> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as ArrayBuffer);
        reader.onerror = () => reject(reader.error);
        reader.readAsArrayBuffer(file);
    });
};

type Row = any[];
type ZraxFilter = 'NONE' | 'ZOP' | 'OZ';

/**
 * Performs the initial data processing: reads files, cleans raw data, and performs VLOOKUPs.
 * Returns the processed data as an array of arrays, ready for the assignment step.
 */
export const runInitialProcessing = async (
    rawFile: File, 
    infoFile: File, 
    dupFile: File, 
    zraxFilter: ZraxFilter,
    defenseKeywords: string
): Promise<Row[]> => {
    // This function processes the three uploaded Excel files.
    // - rawFile: Corresponds to "Excel 1", the main data sheet.
    // - infoFile: Corresponds to "Excel 2", the information sheet (Sheet3 for Info, Sheet2 for Export/Defense).
    // - dupFile: Corresponds to "Excel 3", the duplicate data for the second VLOOKUP.

    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded. Please check the script tag in index.html.');
    }

    // 1. Read all files into workbooks
    const [rawBuffer, infoBuffer, dupBuffer] = await Promise.all([
        readFileAsArrayBuffer(rawFile),
        readFileAsArrayBuffer(infoFile),
        readFileAsArrayBuffer(dupFile),
    ]);

    const rawWb = XLSX.read(rawBuffer, { type: 'array' });
    const infoWb = XLSX.read(infoBuffer, { type: 'array' });
    const dupWb = XLSX.read(dupBuffer, { type: 'array' });

    // 2. Process Raw Data (Excel 1)
    const rawWs = rawWb.Sheets[rawWb.SheetNames[0]];
    if (!rawWs) throw new Error("Raw Data file is empty or corrupted.");
    let rawData: Row[] = XLSX.utils.sheet_to_json(rawWs, { header: 1, defval: "" });

    // 2.1. Apply "Only ZRAX" (OZ) filter if selected
    // Note: This pre-filter logic applies to the RAW data before column removal.
    // User Requirement: Check Column Z (Index 25) for 'ZRAX'.
    if (zraxFilter === 'OZ') {
        const headerRow = rawData.length > 0 ? rawData[0] : [];
        const dataRows = rawData.length > 1 ? rawData.slice(1) : [];
        // Original Column Z is at index 25 (0-based)
        const zraxOnlyData = dataRows.filter(row => String(row[25]).trim() === 'ZRAX');
        rawData = [headerRow, ...zraxOnlyData];
    }

    // 2.2. Convert Col A to numbers and remove duplicates
    const seen = new Set<number>();
    const uniqueData: Row[] = [];
    const header = rawData.length > 0 ? rawData[0] : [];
    uniqueData.push(header); // Keep header

    for (let i = 1; i < rawData.length; i++) {
        const row = rawData[i];
        const valA = Number(row[0]);
        if (!isNaN(valA) && !seen.has(valA)) {
            seen.add(valA);
            row[0] = valA; // Update row with number type
            uniqueData.push(row);
        }
    }
    rawData = uniqueData;

    // 2.3. Delete columns B through H (indices 1 to 7)
    // Keep Index 0 (A). Skip 1-7 (B-H). Keep 8+ (I...).
    rawData = rawData.map(row => [row[0], ...row.slice(8)]);

    // 2.4. Rename Col I (now at index 1) to "CTR" if applicable
    if (rawData.length > 0 && rawData[0].length > 1) {
        rawData[0][1] = 'CTR';
    }

    // 3. Process Info File (Excel 2)

    // 3A. Info Lookup Logic (Existing)
    // Formula: =VLOOKUP(A2,'[Excel 2.xlsx]Sheet3'!$B:$H,6,0)
    const infoSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet3')) || infoWb.SheetNames[0];
    const infoWs = infoWb.Sheets[infoSheetName];
    const infoData: Row[] = XLSX.utils.sheet_to_json(infoWs, { header: 1, defval: "" });

    const infoLookup = new Map<number, any>();
    const infoSeen = new Set<number>();
    for (let i = 1; i < infoData.length; i++) {
        const row = infoData[i];
        const key = Number(row[1]); // Column B
        if (!isNaN(key) && !infoSeen.has(key)) {
            infoSeen.add(key);
            infoLookup.set(key, row[6]); // Column G
        }
    }

    // 3B. Export/Defense Lookup Logic (NEW)
    // Formula: =VLOOKUP(A2,'[...xlsx]Sheet2'!B:H,7,0)
    // Checks 'Sheet2'. Falls back to Info sheet if not found, but prefers Sheet2.
    let exportSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet2'));
    if (!exportSheetName) exportSheetName = infoSheetName; // Fallback

    const exportWs = infoWb.Sheets[exportSheetName];
    // Re-read data if sheet is different, else reuse logic? Safer to read again.
    const exportData: Row[] = XLSX.utils.sheet_to_json(exportWs, { header: 1, defval: "" });
    const exportLookup = new Map<number, string>();

    for (let i = 1; i < exportData.length; i++) {
        const row = exportData[i];
        const key = Number(row[1]); // Column B (Index 1) is lookup key (First col of B:H)
        const value = row[7];       // Column H (Index 7) is return value (7th col of B:H)

        if (!isNaN(key)) {
            exportLookup.set(key, String(value || ""));
        }
    }

    // 4. Process Duplicate File (Excel 3)
    const dupSheetName = dupWb.SheetNames.find((name: string) => name.toLowerCase().includes('master hold report')) || dupWb.SheetNames[0];
    const dupWs = dupWb.Sheets[dupSheetName];
    const dupData: Row[] = XLSX.utils.sheet_to_json(dupWs, { header: 1, defval: "" });

    const dupLookup = new Set<number>();
     for (let i = 1; i < dupData.length; i++) {
        const row = dupData[i];
        const key = Number(row[6]); // Column G
        if (!isNaN(key)) {
            dupLookup.add(key);
        }
    }

    // Prepare Keywords
    const keywords = defenseKeywords.split(',').map(k => k.trim().toLowerCase()).filter(k => k.length > 0);

    // 5. Combine data
    const finalData = rawData.map((row, index) => {
        // Add headers to the first row
        if (index === 0) {
            return [...row, 'Info_VLOOKUP', 'Dup_VLOOKUP', 'Export_Value', 'Defense_Match'];
        }

        const key = row[0];

        // Lookup 1: Info
        const infoValue = infoLookup.get(key) ?? '#N/A';

        // Lookup 2: Dup
        const dupValue = dupLookup.has(key) ? key : '#N/A'; 

        // Lookup 3: Export/Defense
        const exportValue = exportLookup.get(key) ?? '#N/A';

        // Check Keywords
        let isDefenseMatch = 'FALSE';
        if (exportValue !== '#N/A' && keywords.length > 0) {
            const valLower = exportValue.toLowerCase();
            if (keywords.some(kw => valLower.includes(kw))) {
                isDefenseMatch = 'TRUE';
            }
        }

        return [...row, infoValue, dupValue, exportValue, isDefenseMatch];
    });

    return finalData;
};

/**
 * Assigns work, generates the final Excel file, and calculates pivot data.
 * @returns An object containing the .xlsx file data and the pivot table data.
 */
export const assignAndGenerateExcel = async (
    processedData: Row[],
    cnAssignees: string[],
    jpAssignees: string[],
    specialAssignees: string[],
    generalAssignees: string[],
    zraxFilter: ZraxFilter
): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {

    // Create a deep copy of the header to avoid mutation issues
    const header = processedData.length > 0 ? [...processedData[0]] : [];
    if (processedData.length < 2) { // Only header or empty
        const ws = XLSX.utils.aoa_to_sheet([header]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Assigned_Data');
        const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        return { fileData: new Uint8Array(wbout), pivotData: [] };
    }

    const dataRows = processedData.slice(1);

    const dupLookupIndex = header.findIndex((h: string) => h === 'Dup_VLOOKUP');
    if (dupLookupIndex === -1) {
        throw new Error("'Dup_VLOOKUP' column not found. Cannot perform filtering.");
    }

    // 1. Filter rows to keep only those with '#N/A' in 'Dup_VLOOKUP'
    const filteredRows = dataRows.filter(row => row[dupLookupIndex] === '#N/A');

    // Helper function to categorize and assign a given set of rows
    const processAndAssign = (rowsToAssign: Row[]): Row[] => {
        const infoLookupIndex = header.findIndex((h: string) => h === 'Info_VLOOKUP');
        if (infoLookupIndex === -1) throw new Error("'Info_VLOOKUP' column not found.");

        const cnRows: Row[] = [], jpRows: Row[] = [], specialRows: Row[] = [], generalRows: Row[] = [];
        const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY', 'CU', 'IR', 'KP', 'SY']);

        rowsToAssign.forEach((row: Row) => {
            const infoValue = row[infoLookupIndex] ? String(row[infoLookupIndex]).toUpperCase() : '';
            if (infoValue.includes('CN')) cnRows.push([...row]);
            else if (infoValue.includes('JP')) jpRows.push([...row]);
            else if (Array.from(specialCodes).some(code => infoValue.includes(code))) specialRows.push([...row]);
            else generalRows.push([...row]);
        });

        if (cnAssignees.length > 0) cnRows.forEach((row, index) => row.unshift(cnAssignees[index % cnAssignees.length]));
        else cnRows.forEach(row => row.unshift('UNASSIGNED_CN'));

        if (jpAssignees.length > 0) jpRows.forEach((row, index) => row.unshift(jpAssignees[index % jpAssignees.length]));
        else jpRows.forEach(row => row.unshift('UNASSIGNED_JP'));

        if (specialAssignees.length > 0) specialRows.forEach((row, index) => row.unshift(specialAssignees[index % specialAssignees.length]));
        else specialRows.forEach(row => row.unshift('UNASSIGNED_SPECIAL'));

        if (generalAssignees.length > 0) generalRows.forEach((row, index) => row.unshift(generalAssignees[index % generalAssignees.length]));
        else generalRows.forEach(row => row.unshift('UNASSIGNED_GENERAL'));

        return [...cnRows, ...jpRows, ...specialRows, ...generalRows];
    };

    let finalAssignedRows: Row[];

    if (zraxFilter === 'ZOP') {
        const zColIndex = 18; 
        const zraxRows: Row[] = [];
        const otherRows: Row[] = [];

        filteredRows.forEach(row => {
            if (row.length > zColIndex && String(row[zColIndex]).trim() === 'ZRAX') {
                zraxRows.push(row);
            } else {
                otherRows.push(row);
            }
        });

        const assignedZrax = processAndAssign(zraxRows);
        const assignedOthers = processAndAssign(otherRows);
        finalAssignedRows = [...assignedZrax, ...assignedOthers];
    } else {
        finalAssignedRows = processAndAssign(filteredRows);
    }

    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });

    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({
        screener,
        count
    })).sort((a, b) => a.screener.localeCompare(b.screener));

    const ctrIndex = header.findIndex((h: string) => h === 'CTR');
    if (ctrIndex !== -1) {
        header.splice(ctrIndex, 1);
        finalAssignedRows.forEach(row => {
            row.splice(ctrIndex + 1, 1);
        });
    }

    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];

    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);

    const headerStyle = {
        font: { bold: true, color: { rgb: "FFFFFFFF" } },
        fill: { patternType: "solid", fgColor: { rgb: "FF4F46E5" } } 
    };

    const range = XLSX.utils.decode_range(finalWs['!ref']);
    if (range && range.e.r >= 0) { 
        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellAddress = XLSX.utils.encode_cell({ r: 0, c: C });
            const cell = finalWs[cellAddress];
            if (cell) {
                cell.s = headerStyle;
            }
        }
    }

    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'Assigned_Data');

    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    const fileData = new Uint8Array(wbout);

    return { fileData, pivotData };
};

/**
 * Processes GGP Orders data.
 * 1. Removes specific header rows (1,2,3,4,6). Keeps row 5 as header and 7+ as data.
 * 2. Removes Column A (blank) and deduplicates based on the NEW Column A.
 * 3. Filters rows using VLOOKUP against Master Hold Report (Col G).
 */
export const processGGPData = async (rawFile: File, holdFile: File): Promise<Row[]> => {
    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded.');
    }

    const [rawBuffer, holdBuffer] = await Promise.all([
        readFileAsArrayBuffer(rawFile),
        readFileAsArrayBuffer(holdFile)
    ]);
    const rawWb = XLSX.read(rawBuffer, { type: 'array' });
    const holdWb = XLSX.read(holdBuffer, { type: 'array' });

    // 1. Process Raw Data
    const rawWs = rawWb.Sheets[rawWb.SheetNames[0]];
    // Read all rows including empty ones to preserve index mapping for removal
    const rawDataFull: Row[] = XLSX.utils.sheet_to_json(rawWs, { header: 1, defval: "" });

    // Row Removal Logic:
    // Remove Row 1, 2, 3, 4, 6 (Indices 0, 1, 2, 3, 5).
    // Keep Row 5 (Index 4) -> This is the Header.
    // Keep Row 7+ (Indices 6+) -> This is the Data.
    let cleanedRows: Row[] = [];

    if (rawDataFull.length > 4) {
        // Push Header (Row 5 / Index 4)
        cleanedRows.push(rawDataFull[4]);
    }
    if (rawDataFull.length > 6) {
        // Push Data (Row 7+ / Index 6+)
        cleanedRows = cleanedRows.concat(rawDataFull.slice(6));
    }

    if (cleanedRows.length === 0) throw new Error("Processed data is empty after row removal.");

    // 2. Remove Column A (Index 0) and Deduplicate
    // The "Blank" Column A is removed. The old Column B becomes Index 0.
    const seen = new Set<string>();
    const dedupedRows: Row[] = [];

    // Header
    const header = cleanedRows[0].slice(1);
    dedupedRows.push(header);

    for (let i = 1; i < cleanedRows.length; i++) {
        const row = cleanedRows[i];
        // Slice(1) to remove Column A
        const newRow = row.slice(1);

        // Use new Col A (Index 0) for deduping
        // Ensure we check if it has content? The requirement says "Remove duplicates from A column".
        // We convert to string to ensure uniqueness.
        const key = newRow.length > 0 ? String(newRow[0]) : "";

        // Simple check to skip completely empty rows if key is empty?
        // Let's strictly deduplicate.
        if (!seen.has(key)) {
            seen.add(key);
            dedupedRows.push(newRow);
        }
    }

    // 3. VLOOKUP Filter
    // Lookup Key: New Col A (Index 0).
    // Lookup Range: Master Hold Report Col G (Index 6).
    // Logic: If Key exists in Master Hold Col G, remove the row. (Keep only #N/A)
    const holdWs = holdWb.Sheets[holdWb.SheetNames[0]];
    const holdData: Row[] = XLSX.utils.sheet_to_json(holdWs, { header: 1, defval: "" });
    const holdSet = new Set<string>();

    // Build set from Col G (Index 6)
    holdData.forEach(r => {
        if (r.length > 6) {
             holdSet.add(String(r[6]));
        }
    });

    // Filter
    const finalRows: Row[] = [dedupedRows[0]]; // Keep Header
    for (let i = 1; i < dedupedRows.length; i++) {
        const row = dedupedRows[i];
        const key = row.length > 0 ? String(row[0]) : "";

        if (!holdSet.has(key)) {
            finalRows.push(row);
        }
    }

    return finalRows;
};

/**
 * Assigns GGP Data based on high risk codes.
 * Original Raw File Columns:
 * R (Country) = Index 17
 * U (Ship To Country?) = Index 20
 * V = Index 21
 * W = Index 22
 * 
 * After ProcessGGPData (removes Col A):
 * R -> Index 16
 * U -> Index 19
 * V -> Index 20
 * W -> Index 21
 * 
 * Supports two groups:
 * 1. Special (High Risk): RU, VE, NI, BY, UA, CU, IR, KP, SY found in R, U, V, or W
 * 2. General: Everything else
 */
export const assignGGPData = async (
    processedData: Row[],
    specialAssignees: string[],
    generalAssignees: string[]
): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {

    const header = processedData.length > 0 ? [...processedData[0]] : [];
    const dataRows = processedData.slice(1);

    // Indices to check for high risk codes in processed data (0-based)
    // Corresponds to original R (17), U (20), V (21), W (22)
    const highRiskIndices = [16, 19, 20, 21];

    const specialRows: Row[] = [];
    const generalRows: Row[] = [];
    const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY', 'CU', 'IR', 'KP', 'SY']);

    dataRows.forEach((row: Row) => {
        let isHighRisk = false;

        for (const colIndex of highRiskIndices) {
            if (row.length > colIndex && row[colIndex]) {
                 const cellVal = String(row[colIndex]).toUpperCase();
                 // Check if any of the special codes are present in the cell value
                 if (Array.from(specialCodes).some(code => cellVal.includes(code))) {
                     isHighRisk = true;
                     break; 
                 }
            }
        }

        if (isHighRisk) {
            specialRows.push([...row]);
        } else {
            generalRows.push([...row]);
        }
    });

    // Distribute
    if (specialAssignees.length > 0) specialRows.forEach((row, index) => row.unshift(specialAssignees[index % specialAssignees.length]));
    else specialRows.forEach(row => row.unshift('UNASSIGNED_SPECIAL'));

    if (generalAssignees.length > 0) generalRows.forEach((row, index) => row.unshift(generalAssignees[index % generalAssignees.length]));
    else generalRows.forEach(row => row.unshift('UNASSIGNED_GENERAL'));

    const finalAssignedRows = [...specialRows, ...generalRows];

    // Pivot Data
    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });

    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({
        screener,
        count
    })).sort((a, b) => a.screener.localeCompare(b.screener));

    // Final Sheet Creation
    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];
    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);

    const headerStyle = {
        font: { bold: true, color: { rgb: "FFFFFFFF" } },
        fill: { patternType: "solid", fgColor: { rgb: "FF4F46E5" } } 
    };

    const range = XLSX.utils.decode_range(finalWs['!ref']);
    if (range && range.e.r >= 0) { 
        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellAddress = XLSX.utils.encode_cell({ r: 0, c: C });
            const cell = finalWs[cellAddress];
            if (cell) {
                cell.s = headerStyle;
            }
        }
    }

    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'GGP_Assigned');

    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    const fileData = new Uint8Array(wbout);

    return { fileData, pivotData };
};

/**
 * Processes a single Excel file to extract unique numbers from Column A.
 */
export const processColumnA = async (file: File): Promise<{ uniqueNumbers: number[] }> => {
    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded.');
    }

    const buffer = await readFileAsArrayBuffer(file);
    const wb = XLSX.read(buffer, { type: 'array' });
    const ws = wb.Sheets[wb.SheetNames[0]];
    if (!ws) throw new Error("File is empty or corrupted.");

    const data: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });

    const seen = new Set<number>();
    // Iterate through all rows, starting from the first row
    for (let i = 0; i < data.length; i++) {
        const row = data[i];
        // Ensure row and cell exist before processing
        if (row && row.length > 0 && row[0] !== null) {
            const valA = Number(row[0]);
            // Check if the conversion to number is successful
            if (!isNaN(valA)) {
                seen.add(valA);
            }
        }
    }

    return { uniqueNumbers: Array.from(seen).sort((a, b) => a - b) };
};

import React, { useState, useRef } from 'react';
import { CopyIcon, RefreshIcon } from './Icons';

interface PivotData {
    screener: string;
    count: number;
}

interface DashboardProps {
    data: PivotData[];
    onReset: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ data, onReset }) => {
    const [copyStatus, setCopyStatus] = useState('Copy Table');
    const tableRef = useRef<HTMLTableElement>(null);
    const total = data.reduce((sum, item) => sum + item.count, 0);

    const handleCopy = async () => {
        if (!tableRef.current) return;

        try {
            // Create a blob for HTML content to preserve styles
            const tableHTML = tableRef.current.outerHTML;
            const blobHtml = new Blob([tableHTML], { type: 'text/html' });
            const blobText = new Blob([tableRef.current.innerText], { type: 'text/plain' });

            const item = new ClipboardItem({
                'text/html': blobHtml,
                'text/plain': blobText
            });

            await navigator.clipboard.write([item]);

            setCopyStatus('Copied!');
            setTimeout(() => setCopyStatus('Copy Table'), 2000);
        } catch (err) {
            console.error('Clipboard API failed', err);
            // Fallback for environments where Clipboard API might fail or be restricted
            try {
                const range = document.createRange();
                range.selectNode(tableRef.current);
                window.getSelection()?.removeAllRanges();
                window.getSelection()?.addRange(range);
                document.execCommand('copy');
                window.getSelection()?.removeAllRanges();
                setCopyStatus('Copied!');
                setTimeout(() => setCopyStatus('Copy Table'), 2000);
            } catch (fallbackErr) {
                 setCopyStatus('Failed to Copy');
                 setTimeout(() => setCopyStatus('Copy Table'), 2000);
            }
        }
    };

    // Inline styles to match typical Excel Pivot Table formatting
    // Green Header (#548235), White Text, Bold, Black Borders
    const styles = {
        table: {
            borderCollapse: 'collapse' as const,
            width: '100%',
            fontFamily: 'Calibri, Arial, sans-serif',
            fontSize: '11pt',
            backgroundColor: '#ffffff',
            color: '#000000',
            border: '1px solid #000000'
        },
        th: {
            backgroundColor: '#548235', // Excel Green
            color: '#ffffff',
            fontWeight: 'bold',
            border: '1px solid #000000',
            padding: '5px 10px',
            textAlign: 'center' as const // Headers centered
        },
        tdLabel: {
            border: '1px solid #000000',
            padding: '5px 10px',
            textAlign: 'center' as const // Row labels centered based on user request/screenshot inference
        },
        tdCount: {
            border: '1px solid #000000',
            padding: '5px 10px',
            textAlign: 'center' as const
        },
        footerCell: {
            border: '1px solid #000000',
            padding: '5px 10px',
            fontWeight: 'bold',
            textAlign: 'center' as const,
            backgroundColor: '#ffffff',
            color: '#000000'
        }
    };

    return (
        <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl shadow-2xl p-6 sm:p-8 border border-gray-700 animate-fade-in-up">
            <h2 className="text-2xl font-bold mb-6 text-center text-white">Assignment Summary</h2>

            {/* White container for the "sheet" look */}
            <div className="max-w-md mx-auto bg-white p-4 rounded-lg overflow-x-auto shadow-inner">
                <table 
                    ref={tableRef} 
                    id="pivot-table"
                    style={styles.table}
                >
                    <thead>
                        <tr>
                            <th style={styles.th}>Row Labels</th>
                            <th style={styles.th}>Count of Screener</th>
                        </tr>
                    </thead>
                    <tbody>
                        {data.map(({ screener, count }) => (
                            <tr key={screener}>
                                <td style={styles.tdLabel}>{screener}</td>
                                <td style={styles.tdCount}>{count}</td>
                            </tr>
                        ))}
                    </tbody>
                    <tfoot>
                        <tr>
                            <td style={styles.footerCell}>Grand Total</td>
                            <td style={styles.footerCell}>{total}</td>
                        </tr>
                    </tfoot>
                </table>

                <div className="mt-6 flex justify-center">
                     <button
                        onClick={handleCopy}
                        className="inline-flex items-center px-4 py-2 font-semibold text-sm text-white bg-gray-600 rounded-md hover:bg-gray-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-gray-400 transition-colors duration-200"
                    >
                        <CopyIcon />
                        {copyStatus}
                    </button>
                </div>
            </div>

            <div className="mt-8 pt-6 border-t border-gray-700 text-center">
                <button
                    onClick={onReset}
                    className="w-full sm:w-auto inline-flex items-center justify-center px-8 py-3 font-semibold text-lg text-white bg-blue-600 rounded-lg hover:bg-blue-700 focus:outline-none focus:ring-4 focus:ring-blue-500/50 transition-all duration-300 ease-in-out"
                >
                    <RefreshIcon />
                    Process New Files
                </button>
            </div>
             <style>{`
                @keyframes fade-in-up {
                    from { opacity: 0; transform: translateY(20px); }
                    to { opacity: 1; transform: translateY(0); }
                }
                .animate-fade-in-up {
                    animation: fade-in-up 0.3s ease-out forwards;
                }
            `}</style>
        </div>
    );
};

