            )}
             {showAssignmentModal && (
                <AssignmentModal
                    onAssign={handleFinalizeDownload}
                    onCancel={handleCancelAssignment}
                    isAssigning={isAssigning}
                    initialMessage={successMessage}
                />
            )}
        </>
    );
};

