export default AssignerPage;

declare const XLSX: any;

// Helper to read a file into an ArrayBuffer using a Promise
const readFileAsArrayBuffer = (file: File): Promise<ArrayBuffer> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as ArrayBuffer);
        reader.onerror = () => reject(reader.error);
        reader.readAsArrayBuffer(file);
    });
};

type Row = any[];
type ZraxFilter = 'NONE' | 'ZOP' | 'OZ';

/**
 * Performs the initial data processing: reads files, cleans raw data, and performs VLOOKUPs.
 * Returns the processed data as an array of arrays, ready for the assignment step.
 */
export const runInitialProcessing = async (
    rawFile: File, 
    infoFile: File, 
    dupFile: File, 
    zraxFilter: ZraxFilter,
    defenseKeywords: string,
    isDefenseEnabled: boolean
): Promise<Row[]> => {
    if (typeof XLSX === 'undefined') {
        throw new Error('XLSX library is not loaded. Please check the script tag in index.html.');
    }

    // 1. Read all files into workbooks
    const [rawBuffer, infoBuffer, dupBuffer] = await Promise.all([
        readFileAsArrayBuffer(rawFile),
        readFileAsArrayBuffer(infoFile),
        readFileAsArrayBuffer(dupFile),
    ]);

    const rawWb = XLSX.read(rawBuffer, { type: 'array' });
    const infoWb = XLSX.read(infoBuffer, { type: 'array' });
    const dupWb = XLSX.read(dupBuffer, { type: 'array' });

    // 2. Process Raw Data (Excel 1)
    const rawWs = rawWb.Sheets[rawWb.SheetNames[0]];
    if (!rawWs) throw new Error("Raw Data file is empty or corrupted.");
    let rawData: Row[] = XLSX.utils.sheet_to_json(rawWs, { header: 1, defval: "" });

    if (zraxFilter === 'OZ') {
        const headerRow = rawData.length > 0 ? rawData[0] : [];
        const dataRows = rawData.length > 1 ? rawData.slice(1) : [];
        const zraxOnlyData = dataRows.filter(row => String(row[25]).trim() === 'ZRAX');
        rawData = [headerRow, ...zraxOnlyData];
    }

    const seenRaw = new Set<number>();
    const uniqueRawData: Row[] = [];
    const header = rawData.length > 0 ? rawData[0] : [];
    uniqueRawData.push(header);

    for (let i = 1; i < rawData.length; i++) {
        const row = rawData[i];
        const valA = Number(row[0]);
        if (!isNaN(valA) && !seenRaw.has(valA)) {
            seenRaw.add(valA);
            row[0] = valA;
            uniqueRawData.push(row);
        }
    }
    rawData = uniqueRawData;

    rawData = rawData.map(row => [row[0], ...row.slice(8)]);

    if (rawData.length > 0 && rawData[0].length > 1) {
        rawData[0][1] = 'CTR';
    }

    // 3. Process Info File (Excel 2)
    const infoSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet3')) || infoWb.SheetNames[0];
    const infoWs = infoWb.Sheets[infoSheetName];
    const infoData: Row[] = XLSX.utils.sheet_to_json(infoWs, { header: 1, defval: "" });

    const infoLookup = new Map<number, any>();
    const infoSeen = new Set<number>();
    for (let i = 1; i < infoData.length; i++) {
        const row = infoData[i];
        const key = Number(row[1]); // Column B
        if (!isNaN(key)) {
            if (isDefenseEnabled) {
                // If Defense is ENABLED: Do NOT remove duplicates (latest entry wins)
                infoLookup.set(key, row[6]); // Column G
            } else {
                // If Defense is DISABLED: Perform as usual (first entry wins)
                if (!infoSeen.has(key)) {
                    infoSeen.add(key);
                    infoLookup.set(key, row[6]); // Column G
                }
            }
        }
    }

    let exportLookup = new Map<number, string>();
    if (isDefenseEnabled) {
        let exportSheetName = infoWb.SheetNames.find((name: string) => name.toLowerCase().includes('sheet2')) || infoSheetName;
        const exportWs = infoWb.Sheets[exportSheetName];
        const exportData: Row[] = XLSX.utils.sheet_to_json(exportWs, { header: 1, defval: "" });

        for (let i = 1; i < exportData.length; i++) {
            const row = exportData[i];
            const key = Number(row[1]); // Column B
            const value = row[7];       // Column H
            if (!isNaN(key)) {
                // Same logic: overwrite if enabled
                exportLookup.set(key, String(value || ""));
            }
        }
    }

    // 4. Process Duplicate File (Excel 3)
    const dupSheetName = dupWb.SheetNames.find((name: string) => name.toLowerCase().includes('master hold report')) || dupWb.SheetNames[0];
    const dupWs = dupWb.Sheets[dupSheetName];
    const dupData: Row[] = XLSX.utils.sheet_to_json(dupWs, { header: 1, defval: "" });

    const dupLookup = new Set<number>();
     for (let i = 1; i < dupData.length; i++) {
        const row = dupData[i];
        const key = Number(row[6]); // Column G
        if (!isNaN(key)) {
            dupLookup.add(key);
        }
    }

    const keywords = isDefenseEnabled 
        ? defenseKeywords.split(',').map(k => k.trim().toLowerCase()).filter(k => k.length > 0)
        : [];

    // 5. Combine data
    const finalData = rawData.map((row, index) => {
        if (index === 0) {
            return [...row, 'Info_VLOOKUP', 'Dup_VLOOKUP', 'Export_Value', 'Defense_Match'];
        }

        const key = row[0];
        const infoValue = infoLookup.get(key) ?? '#N/A';
        const dupValue = dupLookup.has(key) ? key : '#N/A'; 

        let exportValue = '#N/A';
        let isDefenseMatch = 'FALSE';

        if (isDefenseEnabled) {
            exportValue = exportLookup.get(key) ?? '#N/A';
            if (exportValue !== '#N/A' && keywords.length > 0) {
                const valLower = exportValue.toLowerCase();
                if (keywords.some(kw => valLower.includes(kw))) {
                    isDefenseMatch = 'TRUE';
                }
            }
        }

        return [...row, infoValue, dupValue, exportValue, isDefenseMatch];
    });

    return finalData;
};

export const assignAndGenerateExcel = async (
    processedData: Row[],
    cnAssignees: string[],
    jpAssignees: string[],
    specialAssignees: string[],
    generalAssignees: string[],
    zraxFilter: ZraxFilter
): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {
    const header = processedData.length > 0 ? [...processedData[0]] : [];
    if (processedData.length < 2) {
        const ws = XLSX.utils.aoa_to_sheet([header]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Assigned_Data');
        const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        return { fileData: new Uint8Array(wbout), pivotData: [] };
    }
    const dataRows = processedData.slice(1);
    const dupLookupIndex = header.findIndex((h: string) => h === 'Dup_VLOOKUP');
    if (dupLookupIndex === -1) throw new Error("'Dup_VLOOKUP' column not found.");
    const filteredRows = dataRows.filter(row => row[dupLookupIndex] === '#N/A');
    const processAndAssign = (rowsToAssign: Row[]): Row[] => {
        const infoLookupIndex = header.findIndex((h: string) => h === 'Info_VLOOKUP');
        if (infoLookupIndex === -1) throw new Error("'Info_VLOOKUP' column not found.");
        const cnRows: Row[] = [], jpRows: Row[] = [], specialRows: Row[] = [], generalRows: Row[] = [];
        const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY', 'CU', 'IR', 'KP', 'SY']);
        rowsToAssign.forEach((row: Row) => {
            const infoValue = row[infoLookupIndex] ? String(row[infoLookupIndex]).toUpperCase() : '';
            if (infoValue.includes('CN')) cnRows.push([...row]);
            else if (infoValue.includes('JP')) jpRows.push([...row]);
            else if (Array.from(specialCodes).some(code => infoValue.includes(code))) specialRows.push([...row]);
            else generalRows.push([...row]);
        });
        if (cnAssignees.length > 0) cnRows.forEach((row, index) => row.unshift(cnAssignees[index % cnAssignees.length]));
        else cnRows.forEach(row => row.unshift('UNASSIGNED_CN'));
        if (jpAssignees.length > 0) jpRows.forEach((row, index) => row.unshift(jpAssignees[index % jpAssignees.length]));
        else jpRows.forEach(row => row.unshift('UNASSIGNED_JP'));
        if (specialAssignees.length > 0) specialRows.forEach((row, index) => row.unshift(specialAssignees[index % specialAssignees.length]));
        else specialRows.forEach(row => row.unshift('UNASSIGNED_SPECIAL'));
        if (generalAssignees.length > 0) generalRows.forEach((row, index) => row.unshift(generalAssignees[index % generalAssignees.length]));
        else generalRows.forEach(row => row.unshift('UNASSIGNED_GENERAL'));
        return [...cnRows, ...jpRows, ...specialRows, ...generalRows];
    };
    let finalAssignedRows: Row[];
    if (zraxFilter === 'ZOP') {
        const zColIndex = 18; 
        const zraxRows: Row[] = [];
        const otherRows: Row[] = [];
        filteredRows.forEach(row => {
            if (row.length > zColIndex && String(row[zColIndex]).trim() === 'ZRAX') zraxRows.push(row);
            else otherRows.push(row);
        });
        const assignedZrax = processAndAssign(zraxRows);
        const assignedOthers = processAndAssign(otherRows);
        finalAssignedRows = [...assignedZrax, ...assignedOthers];
    } else {
        finalAssignedRows = processAndAssign(filteredRows);
    }
    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });
    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({ screener, count })).sort((a, b) => a.screener.localeCompare(b.screener));
    const ctrIndex = header.findIndex((h: string) => h === 'CTR');
    if (ctrIndex !== -1) {
        header.splice(ctrIndex, 1);
        finalAssignedRows.forEach(row => row.splice(ctrIndex + 1, 1));
    }
    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];
    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);
    const range = XLSX.utils.decode_range(finalWs['!ref']);
    if (range && range.e.r >= 0) { 
        for (let C = range.s.c; C <= range.e.c; ++C) {
            const cellAddress = XLSX.utils.encode_cell({ r: 0, c: C });
            const cell = finalWs[cellAddress];
            if (cell) cell.s = { font: { bold: true, color: { rgb: "FFFFFFFF" } }, fill: { patternType: "solid", fgColor: { rgb: "FF4F46E5" } } };
        }
    }
    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'Assigned_Data');
    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    return { fileData: new Uint8Array(wbout), pivotData };
};

export const processGGPData = async (rawFile: File, holdFile: File): Promise<Row[]> => {
    if (typeof XLSX === 'undefined') throw new Error('XLSX library is not loaded.');
    const [rawBuffer, holdBuffer] = await Promise.all([readFileAsArrayBuffer(rawFile), readFileAsArrayBuffer(holdFile)]);
    const rawWb = XLSX.read(rawBuffer, { type: 'array' });
    const holdWb = XLSX.read(holdBuffer, { type: 'array' });
    const rawWs = rawWb.Sheets[rawWb.SheetNames[0]];
    const rawDataFull: Row[] = XLSX.utils.sheet_to_json(rawWs, { header: 1, defval: "" });
    let cleanedRows: Row[] = [];
    if (rawDataFull.length > 4) cleanedRows.push(rawDataFull[4]);
    if (rawDataFull.length > 6) cleanedRows = cleanedRows.concat(rawDataFull.slice(6));
    if (cleanedRows.length === 0) throw new Error("Processed data is empty.");
    const seen = new Set<string>();
    const dedupedRows: Row[] = [];
    const header = cleanedRows[0].slice(1);
    dedupedRows.push(header);
    for (let i = 1; i < cleanedRows.length; i++) {
        const newRow = cleanedRows[i].slice(1);
        const key = newRow.length > 0 ? String(newRow[0]) : "";
        if (!seen.has(key)) { seen.add(key); dedupedRows.push(newRow); }
    }
    const holdWs = holdWb.Sheets[holdWb.SheetNames[0]];
    const holdData: Row[] = XLSX.utils.sheet_to_json(holdWs, { header: 1, defval: "" });
    const holdSet = new Set<string>();
    holdData.forEach(r => { if (r.length > 6) holdSet.add(String(r[6])); });
    const finalRows: Row[] = [dedupedRows[0]];
    for (let i = 1; i < dedupedRows.length; i++) {
        const row = dedupedRows[i];
        const key = row.length > 0 ? String(row[0]) : "";
        if (!holdSet.has(key)) finalRows.push(row);
    }
    return finalRows;
};

export const assignGGPData = async (processedData: Row[], specialAssignees: string[], generalAssignees: string[]): Promise<{ fileData: Uint8Array; pivotData: { screener: string; count: number }[] }> => {
    const header = processedData.length > 0 ? [...processedData[0]] : [];
    const dataRows = processedData.slice(1);
    const highRiskIndices = [16, 19, 20, 21];
    const specialRows: Row[] = [];
    const generalRows: Row[] = [];
    const specialCodes = new Set(['RU', 'UA', 'NI', 'VE', 'BY', 'CU', 'IR', 'KP', 'SY']);
    dataRows.forEach((row: Row) => {
        let isHighRisk = false;
        for (const colIndex of highRiskIndices) {
            if (row.length > colIndex && row[colIndex]) {
                 const cellVal = String(row[colIndex]).toUpperCase();
                 if (Array.from(specialCodes).some(code => cellVal.includes(code))) { isHighRisk = true; break; }
            }
        }
        if (isHighRisk) specialRows.push([...row]);
        else generalRows.push([...row]);
    });
    if (specialAssignees.length > 0) specialRows.forEach((row, index) => row.unshift(specialAssignees[index % specialAssignees.length]));
    else specialRows.forEach(row => row.unshift('UNASSIGNED_SPECIAL'));
    if (generalAssignees.length > 0) generalRows.forEach((row, index) => row.unshift(generalAssignees[index % generalAssignees.length]));
    else generalRows.forEach(row => row.unshift('UNASSIGNED_GENERAL'));
    const finalAssignedRows = [...specialRows, ...generalRows];
    const screenerCounts = new Map<string, number>();
    finalAssignedRows.forEach(row => {
        const screener = row[0] as string;
        screenerCounts.set(screener, (screenerCounts.get(screener) || 0) + 1);
    });
    const pivotData = Array.from(screenerCounts.entries()).map(([screener, count]) => ({ screener, count })).sort((a, b) => a.screener.localeCompare(b.screener));
    header.unshift('Screener');
    const finalSheetData = [header, ...finalAssignedRows];
    const finalWs = XLSX.utils.aoa_to_sheet(finalSheetData);
    const finalWb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(finalWb, finalWs, 'GGP_Assigned');
    const wbout = XLSX.write(finalWb, { bookType: 'xlsx', type: 'array' });
    return { fileData: new Uint8Array(wbout), pivotData };
};

export const processColumnA = async (file: File): Promise<{ uniqueNumbers: number[] }> => {
    if (typeof XLSX === 'undefined') throw new Error('XLSX library is not loaded.');
    const buffer = await readFileAsArrayBuffer(file);
    const wb = XLSX.read(buffer, { type: 'array' });
    const ws = wb.Sheets[wb.SheetNames[0]];
    const data: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });
    const seen = new Set<number>();
    for (let i = 0; i < data.length; i++) {
        const row = data[i];
        if (row && row.length > 0 && row[0] !== null) {
            const valA = Number(row[0]);
            if (!isNaN(valA)) seen.add(valA);
        }
    }
    return { uniqueNumbers: Array.from(seen).sort((a, b) => a - b) };
};

import React, { useState, useCallback, useEffect } from 'react';
import type { ExcelFileState } from '../types';
import { runInitialProcessing, assignAndGenerateExcel } from '../services/excelProcessor';
import FileUploader from './FileUploader';
import AssignmentModal from './AssignmentModal';
import Dashboard from './Dashboard';
import { PlayIcon, SpinnerIcon } from './Icons';

declare const saveAs: any;

const STORAGE_KEY_KEYWORDS = 'tchub_defense_keywords';
const STORAGE_KEY_ENABLED = 'tchub_defense_enabled';

const ShieldIcon: React.FC<{ active?: boolean }> = ({ active }) => (
    <svg className={`w-5 h-5 mr-2 transition-colors duration-200 ${active ? 'text-yellow-400' : 'text-gray-500'}`} xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75m-3-7.036A11.959 11.959 0 013.598 6 11.99 11.99 0 003 9.74c0 3.892 1.851 7.347 4.725 9.512a11.957 11.957 0 0014.25 0C22.149 17.087 24 13.632 24 9.74c0-1.313-.21-2.579-.598-3.763a11.959 11.959 0 01-8.402-4.763z" />
    </svg>
);

const AssignerPage: React.FC = () => {
    const [files, setFiles] = useState<ExcelFileState>({
        raw: null,
        info: null,
        duplicate: null,
    });
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [isAssigning, setIsAssigning] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [successMessage, setSuccessMessage] = useState<string | null>(null);
    const [processedDataForAssignment, setProcessedDataForAssignment] = useState<any[] | null>(null);
    const [showAssignmentModal, setShowAssignmentModal] = useState<boolean>(false);
    const [pivotData, setPivotData] = useState<{ screener: string; count: number }[] | null>(null);
    const [showDashboard, setShowDashboard] = useState<boolean>(false);
    const [zraxFilter, setZraxFilter] = useState<'NONE' | 'ZOP' | 'OZ'>('NONE');
    const [isKeywordsExpanded, setIsKeywordsExpanded] = useState<boolean>(false);

    // Initialize state from localStorage if available
    const [defenseKeywords, setDefenseKeywords] = useState<string>(() => {
        const saved = localStorage.getItem(STORAGE_KEY_KEYWORDS);
        return saved !== null ? saved : 'Lockheed, Raytheon, Northrop, Bae';
    });

    const [isDefenseEnabled, setIsDefenseEnabled] = useState<boolean>(() => {
        const saved = localStorage.getItem(STORAGE_KEY_ENABLED);
        return saved === 'true'; // Default to false if not found
    });

    // Save to localStorage whenever defense settings change
    useEffect(() => {
        localStorage.setItem(STORAGE_KEY_KEYWORDS, defenseKeywords);
        localStorage.setItem(STORAGE_KEY_ENABLED, String(isDefenseEnabled));
    }, [defenseKeywords, isDefenseEnabled]);

    const handleFileChange = (fileType: keyof ExcelFileState) => (file: File | null) => {
        setFiles(prev => ({ ...prev, [fileType]: file }));
        setError(null);
        setSuccessMessage(null);
    };

    const resetState = () => {
        setFiles({ raw: null, info: null, duplicate: null });
        setProcessedDataForAssignment(null);
        setShowAssignmentModal(false);
        setIsAssigning(false);
        setShowDashboard(false);
        setPivotData(null);
        setError(null);
        setSuccessMessage(null);
        setZraxFilter('NONE');
    };

    const handleProcess = useCallback(async () => {
        if (!files.raw || !files.info || !files.duplicate) {
            setError("Please upload all three required Excel files.");
            return;
        }

        setIsLoading(true);
        setError(null);
        setSuccessMessage(null);

        try {
            const processedData = await runInitialProcessing(
                files.raw, 
                files.info, 
                files.duplicate, 
                zraxFilter, 
                defenseKeywords,
                isDefenseEnabled
            );
            setProcessedDataForAssignment(processedData);
            setShowAssignmentModal(true);
            setSuccessMessage("Step 1 Complete: Data processed. Now assign screeners.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred: ${e.message}`);
            } else {
                setError("An unknown error occurred during processing.");
            }
        } finally {
            setIsLoading(false);
        }
    }, [files, zraxFilter, defenseKeywords, isDefenseEnabled]);

    const handleFinalizeDownload = async (cnNames: string[], jpNames: string[], specialNames: string[], generalNames: string[]) => {
        if (!processedDataForAssignment) return;

        setIsAssigning(true);
        setError(null);

        try {
            const { fileData, pivotData } = await assignAndGenerateExcel(processedDataForAssignment, cnNames, jpNames, specialNames, generalNames, zraxFilter);
            const blob = new Blob([fileData], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
            saveAs(blob, "Assigned_Report.xlsx");

            setPivotData(pivotData);
            setShowDashboard(true);
            setShowAssignmentModal(false);
            setSuccessMessage("Success! Your download has started. See assignment summary below.");
        } catch (e) {
            if (e instanceof Error) {
                setError(`An error occurred during assignment: ${e.message}`);
            } else {
                setError("An unknown error occurred during assignment.");
            }
        } finally {
            setIsAssigning(false);
        }
    };

    const handleCancelAssignment = () => {
        setShowAssignmentModal(false);
        setProcessedDataForAssignment(null);
        setSuccessMessage(null);
    };

    const handleZraxFilterChange = (filter: 'ZOP' | 'OZ') => {
        setZraxFilter(prev => (prev === filter ? 'NONE' : filter));
    };

    const getFilterButtonClasses = (filter: 'ZOP' | 'OZ') => `
        px-3 py-1 text-xs font-bold rounded-full transition-colors duration-200 border-2 
        ${zraxFilter === filter
            ? 'bg-purple-600 border-purple-500 text-white shadow-lg'
            : 'bg-gray-700/50 border-gray-600 text-gray-300 hover:bg-gray-600'
        }
    `;

    const allFilesUploaded = files.raw && files.info && files.duplicate;

    return (
        <>
            <header className="text-center mb-8">
                <h1 className="text-4xl sm:text-5xl font-extrabold mb-2 bg-gradient-to-r from-blue-400 to-purple-500 text-transparent bg-clip-text">
                    TCHUB Assigner
                </h1>
                <p className="text-lg text-gray-400">
                    Automate your data workflow: Process, Assign, and Download.
                </p>
            </header>

            {error && (
                <div className="mb-6 p-4 text-center text-red-300 bg-red-900/50 border border-red-700 rounded-lg">
                    <strong>Error:</strong> {error}
                </div>
            )}
            {successMessage && !showAssignmentModal && (
                <div className="mb-6 p-4 text-center text-green-300 bg-green-900/50 border border-green-700 rounded-lg">
                    {successMessage}
                </div>
            )}

            {showDashboard && pivotData ? (
                 <Dashboard data={pivotData} onReset={resetState} />
            ) : (
                <main className="bg-gray-800/50 backdrop-blur-sm rounded-2xl shadow-2xl p-6 sm:p-8 border border-gray-700">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                        <FileUploader
                            id="raw-data"
                            label="1. Raw Data Sheet"
                            description="Main data to be assigned."
                            onFileSelect={handleFileChange('raw')}
                            fileName={files.raw?.name}
                        />
                        <FileUploader
                            id="info-data"
                            label="2. Information Sheet"
                            description="Contains VLOOKUP data (Sheet3 & Sheet2)."
                            onFileSelect={handleFileChange('info')}
                            fileName={files.info?.name}
                        />
                        <FileUploader
                            id="duplicate-data"
                            label="3. Duplicate Data Sheet"
                            description="Master Hold Report."
                            onFileSelect={handleFileChange('duplicate')}
                            fileName={files.duplicate?.name}
                        />
                    </div>

                    <div className="mb-8 border border-gray-700 rounded-lg overflow-hidden">
                        <div className="flex items-center w-full bg-gray-800/80 p-4 border-b border-gray-700/50">
                            <input 
                                type="checkbox" 
                                id="defense-toggle"
                                checked={isDefenseEnabled}
                                onChange={(e) => setIsDefenseEnabled(e.target.checked)}
                                className="w-5 h-5 text-purple-600 bg-gray-900 border-gray-600 rounded focus:ring-purple-500 focus:ring-offset-gray-800"
                            />
                            <button
                                onClick={() => setIsKeywordsExpanded(!isKeywordsExpanded)}
                                className="flex-grow flex justify-between items-center ml-4 text-left focus:outline-none"
                            >
                                <span className="flex items-center text-sm font-medium text-purple-300">
                                    <ShieldIcon active={isDefenseEnabled} />
                                    High risk keywords
                                    {!isDefenseEnabled && <span className="ml-2 text-[10px] text-gray-500 font-bold tracking-wider uppercase">(Disabled)</span>}
                                </span>
                                <svg
                                    className={`w-5 h-5 text-gray-400 transform transition-transform duration-200 ${isKeywordsExpanded ? 'rotate-180' : ''}`}
                                    fill="none"
                                    viewBox="0 0 24 24"
                                    stroke="currentColor"
                                >
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                                </svg>
                            </button>
                        </div>

                        {isKeywordsExpanded && (
                            <div className={`p-4 bg-gray-900/50 transition-opacity duration-200 ${!isDefenseEnabled ? 'opacity-50' : 'opacity-100'}`}>
                                <label htmlFor="defense-keywords" className="block text-xs text-gray-400 mb-2">
                                    {isDefenseEnabled 
                                        ? "Checks value from Info Sheet (Sheet2, Col H). Duplicates in Excel 2 will NOT be removed."
                                        : "Enable this to perform keyword matching and skip duplicate removal for Excel 2."}
                                </label>
                                <textarea
                                    id="defense-keywords"
                                    rows={2}
                                    disabled={!isDefenseEnabled}
                                    className={`w-full bg-gray-900 border border-gray-600 rounded-md p-3 text-white focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition ${!isDefenseEnabled ? 'cursor-not-allowed' : ''}`}
                                    placeholder="e.g. Lockheed, Raytheon, Northrop, Bae"
                                    value={defenseKeywords}
                                    onChange={(e) => setDefenseKeywords(e.target.value)}
                                />
                                {isDefenseEnabled && (
                                    <p className="mt-1 text-xs text-gray-500">
                                        Result will be 'TRUE' in the final column if any keywords match.
                                    </p>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="mt-8 flex flex-col sm:flex-row justify-center items-center gap-4">
                        <div className="flex items-center gap-2 p-2 bg-gray-900/50 border border-gray-700 rounded-full order-1 sm:order-2">
                            <button
                                onClick={() => handleZraxFilterChange('ZOP')}
                                className={getFilterButtonClasses('ZOP')}
                                title="Prioritize 'ZRAX' rows from Processed Column S"
                            >
                                ZOP
                            </button>
                            <button
                                onClick={() => handleZraxFilterChange('OZ')}
                                className={getFilterButtonClasses('OZ')}
                                title="Keep ONLY 'ZRAX' rows from Original Column Z"
                            >
                                OZ
                            </button>
                        </div>
                        <button
                            onClick={handleProcess}
                            disabled={!allFilesUploaded || isLoading}
                            className="w-full sm:w-auto inline-flex items-center justify-center px-8 py-4 font-semibold text-lg text-white bg-blue-600 rounded-lg hover:bg-blue-700 disabled:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-4 focus:ring-blue-500/50 transition-all duration-300 ease-in-out shadow-lg transform hover:scale-105 order-2 sm:order-1"
                        >
                            {isLoading ? (
                                <>
                                    <SpinnerIcon />
                                    Processing...
                                </>
                            ) : (
                                <>
                                    <PlayIcon />
                                    Process Files
                                </>
                            )}
                        </button>
                    </div>
                </main>
            )}
             {showAssignmentModal && (
                <AssignmentModal
                    onAssign={handleFinalizeDownload}
                    onCancel={handleCancelAssignment}
                    isAssigning={isAssigning}
                    initialMessage={successMessage}
                />
            )}
        </>
    );
};

export default AssignerPage;
